.fxl-loupe {
  /* Re-theme with these four; tints, rules and the glass are derived. */
  --fxl-loupe-paper: oklch(0.965 0.014 84);
  --fxl-loupe-ink: oklch(0.27 0.025 240);
  --fxl-loupe-accent: oklch(0.56 0.15 32);
  --fxl-loupe-glass: oklch(0.985 0.008 200);

  --fxl-loupe-muted: color-mix(in oklch, var(--fxl-loupe-ink) 56%, var(--fxl-loupe-paper));
  --fxl-loupe-rule: color-mix(in oklch, var(--fxl-loupe-ink) 13%, transparent);
  --fxl-loupe-well: color-mix(in oklch, var(--fxl-loupe-ink) 4%, var(--fxl-loupe-paper));
  --fxl-loupe-out: cubic-bezier(.16, 1, .3, 1);
  --fxl-loupe-spring: linear(0, 0.07 4%, 0.26 9%, 0.74 20%, 0.96 27%, 1.07 33%, 1.1 38%, 1.08 44%, 1.02 54%, 0.99 63%, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  min-block-size: 158px;
  margin: 0;
  display: grid;
  grid-template-areas: "head" "stage" "read";
  grid-template-rows: auto 1fr auto;
  gap: clamp(8px, 3cqi, 12px);
  padding: clamp(12px, 4.4cqi, 18px);
  border-radius: 16px;
  color: var(--fxl-loupe-ink);
  background:
    radial-gradient(120% 70% at 85% -10%, color-mix(in oklch, var(--fxl-loupe-accent) 7%, transparent), transparent 60%),
    var(--fxl-loupe-paper);
  box-shadow: inset 0 0 0 1px var(--fxl-loupe-rule);
  font: 400 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3, ol) { margin: 0; padding: 0; }
}
.fxl-loupe .fxl-loupe-defs { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }

.fxl-loupe .fxl-loupe-head {
  grid-area: head;
  display: grid;
  grid-template-areas: "eyebrow zoom" "title zoom";
  grid-template-columns: 1fr auto;
  align-items: center;
  column-gap: 10px;
}
.fxl-loupe .fxl-loupe-eyebrow {
  grid-area: eyebrow;
  font: 600 9.5px/1.2 ui-monospace, Menlo, monospace;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--fxl-loupe-muted);
}
.fxl-loupe .fxl-loupe-title {
  grid-area: title;
  margin-block-start: 3px;
  font-size: clamp(14px, 5cqi, 18px);
  font-weight: 650;
  letter-spacing: -.018em;
  line-height: 1.12;
  text-wrap: balance;
}
.fxl-loupe .fxl-loupe-zoom {
  grid-area: zoom;
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  block-size: 30px;
  padding: 0 10px 0 7px;
  border: 1px solid var(--fxl-loupe-rule);
  border-radius: 999px;
  background: color-mix(in oklch, var(--fxl-loupe-paper) 70%, white);
  color: inherit;
  font: 600 11px/1 ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: background .2s, border-color .2s, scale .35s var(--fxl-loupe-spring);
  & svg { inline-size: 16px; block-size: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
  &:hover { border-color: color-mix(in oklch, var(--fxl-loupe-ink) 30%, transparent); }
  &:active { scale: .95; }
  &[aria-pressed="true"] {
    background: var(--fxl-loupe-ink);
    border-color: var(--fxl-loupe-ink);
    color: var(--fxl-loupe-paper);
  }
  &:focus-visible { outline: 2px solid var(--fxl-loupe-accent); outline-offset: 2px; }
}

.fxl-loupe .fxl-loupe-stage {
  grid-area: stage;
  position: relative;
  min-block-size: 0;
  border-radius: 12px;
  outline: none;
  cursor: crosshair;
  touch-action: pan-y;
  &:focus-visible { box-shadow: 0 0 0 2px var(--fxl-loupe-paper), 0 0 0 4px var(--fxl-loupe-accent); }
}
.fxl-loupe .fxl-loupe-sheet {
  --fxl-loupe-cols: 4;
  list-style: none;
  display: grid;
  grid-template-columns: repeat(var(--fxl-loupe-cols), minmax(0, 1fr));
  gap: 7px 4px;
  padding: 8px 4px 6px;
  border-radius: 12px;
  background:
    linear-gradient(var(--fxl-loupe-rule), var(--fxl-loupe-rule)) 0 0 / 100% 1px no-repeat,
    var(--fxl-loupe-well);
}
@container (min-width: 330px) { .fxl-loupe .fxl-loupe-sheet { --fxl-loupe-cols: 5; } }
@container (min-width: 500px) { .fxl-loupe .fxl-loupe-sheet { --fxl-loupe-cols: 7; } }

.fxl-loupe .fxl-loupe-chip {
  display: grid;
  justify-items: center;
  align-content: start;
  gap: 1px;
  min-inline-size: 0;
  text-align: center;
  transition: opacity .5s var(--fxl-loupe-out), translate .6s var(--fxl-loupe-out);
  transition-delay: calc(var(--i) * 28ms);
  @starting-style { opacity: 0; translate: 0 5px; }
}
.fxl-loupe .fxl-loupe-pebble {
  inline-size: min(72%, 40px);
  aspect-ratio: 1.18;
  margin-block-end: 3px;
  border-radius: var(--r);
  background:
    radial-gradient(70% 55% at 32% 26%, color-mix(in oklch, white 62%, transparent), transparent 62%),
    radial-gradient(90% 80% at 70% 85%, color-mix(in oklch, var(--c) 72%, black), transparent 70%),
    var(--c);
  box-shadow:
    inset 0 -2px 4px color-mix(in oklch, var(--c) 55%, black 18%),
    inset 0 1px 1.5px color-mix(in oklch, white 70%, transparent),
    0 1.5px 2px color-mix(in oklch, var(--fxl-loupe-ink) 22%, transparent);
  opacity: .93;
}
.fxl-loupe .fxl-loupe-cname {
  max-inline-size: 100%;
  overflow: hidden;
  font-size: clamp(7.5px, 2.35cqi, 9.5px);
  font-weight: 650;
  letter-spacing: -.01em;
  white-space: nowrap;
  text-overflow: clip;
}
.fxl-loupe .fxl-loupe-share,
.fxl-loupe .fxl-loupe-odds {
  font: 500 clamp(6.5px, 2cqi, 8px)/1.15 ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  color: var(--fxl-loupe-muted);
  white-space: nowrap;
}
.fxl-loupe .fxl-loupe-share { color: var(--fxl-loupe-ink); }

/* the lens: squash on the outer box, clip on the glass, filter on an oversized fx layer */
.fxl-loupe .fxl-loupe-lens {
  position: absolute;
  left: 0;
  top: 0;
  inline-size: 120px;
  block-size: 72px;
  pointer-events: auto;
  touch-action: none;
  will-change: transform;
}
.fxl-loupe .fxl-loupe-glass {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: 999px;
  background: var(--fxl-loupe-well);
  box-shadow:
    0 14px 26px -12px color-mix(in oklch, var(--fxl-loupe-ink) 50%, transparent),
    0 3px 7px -2px color-mix(in oklch, var(--fxl-loupe-ink) 22%, transparent);
}
.fxl-loupe .fxl-loupe-fx { position: absolute; inset: -26px; }
.fxl-loupe .fxl-loupe-lensed {
  position: absolute;
  left: 0;
  top: 0;
  margin: 0;
  transform-origin: 0 0;
  pointer-events: none;
  & .fxl-loupe-chip { transition: none; }
}
.fxl-loupe .fxl-loupe-rim {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  pointer-events: none;
  background:
    radial-gradient(40% 30% at 26% 18%, color-mix(in oklch, var(--fxl-loupe-glass) 26%, transparent), transparent 70%),
    radial-gradient(50% 40% at 80% 96%, color-mix(in oklch, var(--fxl-loupe-glass) 18%, transparent), transparent 70%);
  box-shadow:
    inset 0 1.5px 0 color-mix(in oklch, white 90%, transparent),
    inset 0 -1.5px 1px color-mix(in oklch, white 40%, transparent),
    inset 0 0 0 .75px color-mix(in oklch, var(--fxl-loupe-ink) 22%, transparent),
    inset 0 0 6px 1px color-mix(in oklch, var(--fxl-loupe-glass) 30%, transparent);
}
.fxl-loupe .fxl-loupe-rim::after {
  content: "";
  position: absolute;
  inset: 2px 16% auto;
  block-size: 9px;
  border-radius: 999px;
  background: linear-gradient(color-mix(in oklch, white 70%, transparent), transparent);
  filter: blur(.5px);
  opacity: .55;
}
.fxl-loupe:has(.fxl-loupe-stage:focus-visible) .fxl-loupe-rim {
  outline: 2px solid var(--fxl-loupe-accent);
  outline-offset: 3px;
}

.fxl-loupe .fxl-loupe-read {
  grid-area: read;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
  padding-block-start: 9px;
  border-block-start: 1px solid var(--fxl-loupe-rule);
  font-variant-numeric: tabular-nums;
}
.fxl-loupe .fxl-loupe-swatch {
  inline-size: 12px;
  aspect-ratio: 1;
  border-radius: 46% 54% 40% 60% / 56% 44% 58% 42%;
  background: var(--fxl-loupe-sw, oklch(0.44 0.17 264));
  box-shadow: inset 0 -1px 2px color-mix(in oklch, black 25%, transparent);
  transition: background-color .4s var(--fxl-loupe-out);
}
.fxl-loupe .fxl-loupe-name {
  overflow: hidden;
  font-size: 13px;
  font-weight: 650;
  letter-spacing: -.01em;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.fxl-loupe .fxl-loupe-stat,
.fxl-loupe .fxl-loupe-rare {
  font: 500 10.5px/1 ui-monospace, Menlo, monospace;
  color: var(--fxl-loupe-muted);
  white-space: nowrap;
}
.fxl-loupe .fxl-loupe-rare {
  padding: 4px 7px;
  border-radius: 999px;
  color: var(--fxl-loupe-accent);
  background: color-mix(in oklch, var(--fxl-loupe-accent) 11%, transparent);
  font-weight: 650;
}
@container (max-width: 300px) {
  .fxl-loupe .fxl-loupe-stat { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .fxl-loupe .fxl-loupe-chip { transition: none; }
  .fxl-loupe .fxl-loupe-zoom { transition: background .2s, border-color .2s; }
  .fxl-loupe .fxl-loupe-zoom:active { scale: 1; }
  .fxl-loupe .fxl-loupe-swatch { transition: none; }
}

