const stage = root.querySelector('.fxl-loupe-stage');
const sheet = root.querySelector('.fxl-loupe-sheet');
const lens = root.querySelector('.fxl-loupe-lens');
const fx = root.querySelector('.fxl-loupe-fx');
const filter = root.querySelector('.fxl-loupe-filter');
const feImg = root.querySelector('.fxl-loupe-map');
const maps = root.querySelectorAll('feDisplacementMap');
const zoomBtn = root.querySelector('.fxl-loupe-zoom');
const zx = root.querySelector('.fxl-loupe-zx');
const read = root.querySelector('.fxl-loupe-read');
const nameEl = root.querySelector('.fxl-loupe-name');
const countEl = root.querySelector('.fxl-loupe-count');
const inEl = root.querySelector('.fxl-loupe-in');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* Filter ids are document-global: give this instance its own. */
const uid = 'fxl-loupe-' + Math.random().toString(36).slice(2, 9);
filter.id = uid;
fx.style.filter = 'url(#' + uid + ')';

/* The lens shows a live clone of the chart. Magnification is a plain transform on the
   clone (so text stays vector-sharp); only the bezel is done by the SVG filter, from a
   displacement map computed for the capsule's signed distance field. */
const clone = sheet.cloneNode(true);
clone.classList.add('fxl-loupe-lensed');
clone.removeAttribute('aria-label');
clone.setAttribute('aria-hidden', 'true');
clone.inert = true;
fx.appendChild(clone);

const P = 26;                               /* fx layer overhang, so the rim can sample outside the lens */
const chips = [...sheet.children];
let W = 0, H = 0, lw = 120, lh = 72, ox = 0, oy = 0, centers = [];
let x = 0, y = 0, vx = 0, vy = 0, tx = 0, ty = 0, mag = 1.5, lift = 0;
let zoomed = false, dragging = false, lastInput = -1e9, tourAt = 0, tourK = 0, cur = -1;
let raf = 0, last = 0, visible = true, mapped = '';
const TOUR = [6, 11, 3, 12, 8, 5, 9, 1, 13, 4, 10, 7, 2, 0];

function buildMap() {
  const key = lw + 'x' + lh;
  if (key === mapped) return;
  mapped = key;
  const cv = document.createElement('canvas');
  cv.width = lw; cv.height = lh;
  const g = cv.getContext('2d');
  const img = g.createImageData(lw, lh), d = img.data;
  const r = lh / 2, hx = lw / 2 - r, B = Math.max(7, Math.min(13, lh * 0.17));
  const maxD = B * 1.35, S = maxD * 2.08;
  for (let j = 0; j < lh; j++) {
    for (let i = 0; i < lw; i++) {
      const px = i + 0.5 - lw / 2, py = j + 0.5 - lh / 2, qx = Math.abs(px) - hx;
      let dist, nx, ny;
      if (qx > 0) { const L = Math.hypot(qx, py) || 1; dist = L - r; nx = Math.sign(px) * qx / L; ny = py / L; }
      else { dist = Math.abs(py) - r; nx = 0; ny = Math.sign(py) || 1; }
      const t = -dist;                        /* depth inside the glass, 0 at the edge */
      let dx = 0, dy = 0;
      if (t > 0 && t < B) {
        const u = 1 - t / B;                  /* 1 at the rim, 0 where the bezel meets the flat top */
        const k = Math.pow(u, 2.2) * (1 - 0.25 * u * u);
        dx = -nx * maxD * k; dy = -ny * maxD * k;
      }
      const o = (j * lw + i) * 4;
      d[o] = Math.max(0, Math.min(255, Math.round(127.5 + dx / S * 255)));
      d[o + 1] = Math.max(0, Math.min(255, Math.round(127.5 + dy / S * 255)));
      d[o + 2] = 128; d[o + 3] = 255;
    }
  }
  g.putImageData(img, 0, 0);
  feImg.setAttribute('href', cv.toDataURL());
  feImg.setAttribute('x', P); feImg.setAttribute('y', P);
  feImg.setAttribute('width', lw); feImg.setAttribute('height', lh);
  maps[0].setAttribute('scale', S.toFixed(2));
  maps[1].setAttribute('scale', (S * 1.07).toFixed(2));
  maps[2].setAttribute('scale', (S * 1.14).toFixed(2));
}

function measure() {
  W = stage.clientWidth; H = stage.clientHeight;
  if (!W || !H) return;
  lw = Math.round(Math.max(92, Math.min(138, W * 0.36)));
  lh = Math.round(lw * 0.64);
  lens.style.width = lw + 'px'; lens.style.height = lh + 'px';
  ox = sheet.offsetLeft; oy = sheet.offsetTop;
  clone.style.width = sheet.offsetWidth + 'px';
  clone.style.height = sheet.offsetHeight + 'px';
  const s = stage.getBoundingClientRect();
  centers = chips.map((li) => {
    const p = li.querySelector('.fxl-loupe-cname').getBoundingClientRect(), b = li.getBoundingClientRect();
    return [b.left - s.left + b.width / 2, p.top - s.top + 1];
  });
  buildMap();
  if (cur < 0) { cur = 6; [x, y] = centers[6]; tx = x; ty = y; }
  else { [tx, ty] = centers[cur]; }
  render(0);
}

function clampT() {
  tx = Math.max(lw * 0.3, Math.min(W - lw * 0.3, tx));
  ty = Math.max(lh * 0.3, Math.min(H - lh * 0.3, ty));
}

function nearest(px, py) {
  let best = -1, bd = 1e9;
  centers.forEach((c, i) => { const d = Math.hypot(c[0] - px, (c[1] - py) * 1.3); if (d < bd) { bd = d; best = i; } });
  return bd < lw * 0.42 ? best : -1;
}

let shown = -2;
function show(i) {
  if (i === shown) return;
  shown = i;
  if (i < 0) { nameEl.textContent = 'Between colours'; countEl.textContent = '—'; inEl.textContent = '—'; return; }
  const li = chips[i], n = +li.dataset.n;
  nameEl.textContent = li.querySelector('.fxl-loupe-cname').textContent;
  countEl.textContent = n.toLocaleString('en-GB');
  inEl.textContent = Math.round(10000 / n).toLocaleString('en-GB');
  root.style.setProperty('--fxl-loupe-sw', li.style.getPropertyValue('--c'));
}

function render(spd) {
  const calm = reduce.matches;
  const st = calm ? 0 : Math.min(0.16, spd * 0.00042);
  const ang = Math.atan2(vy, vx);
  let sx = 1 + st * Math.abs(Math.cos(ang)) - st * 0.5 * Math.abs(Math.sin(ang));
  let sy = 1 + st * Math.abs(Math.sin(ang)) - st * 0.5 * Math.abs(Math.cos(ang));
  const up = 1 + lift * 0.07;
  sx *= up; sy *= up;
  lens.style.transform = 'translate(' + (x - lw / 2).toFixed(2) + 'px,' + (y - lh / 2).toFixed(2) + 'px) scale(' + sx.toFixed(4) + ',' + sy.toFixed(4) + ')';
  const m = mag, a = m / sx, dd = m / sy;
  const e = P + lw / 2 + a * (ox - x), f = P + lh / 2 + dd * (oy - y);
  clone.style.transform = 'matrix(' + a.toFixed(4) + ',0,0,' + dd.toFixed(4) + ',' + e.toFixed(2) + ',' + f.toFixed(2) + ')';
  show(nearest(x, y));
}

function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible || !W) return;
  const dt = Math.min(0.034, (now - last) / 1000 || 0.016); last = now;
  const calm = reduce.matches;
  if (!calm && !dragging && now - lastInput > 5200 && now > tourAt) {
    tourK = (tourK + 1) % TOUR.length;
    cur = TOUR[tourK]; [tx, ty] = centers[cur];
    tourAt = now + 2600;
  }
  clampT();
  const magT = (zoomed ? 2.05 : 1.5) + lift * 0.14;
  if (calm) {
    const f = 1 - Math.pow(0.0001, dt);
    x += (tx - x) * f; y += (ty - y) * f; vx = vy = 0; mag += (magT - mag) * f;
    lift += ((dragging ? 1 : 0) - lift) * f;
  } else {
    const k = dragging ? 520 : 210, c = dragging ? 38 : 19;
    vx += ((tx - x) * k - vx * c) * dt; vy += ((ty - y) * k - vy * c) * dt;
    x += vx * dt; y += vy * dt;
    mag += (magT - mag) * (1 - Math.pow(0.002, dt));
    lift += ((dragging ? 1 : 0) - lift) * (1 - Math.pow(0.0005, dt));
  }
  render(Math.hypot(vx, vy));
  const moving = Math.abs(tx - x) + Math.abs(ty - y) + Math.abs(vx) + Math.abs(vy) > 0.05 || Math.abs(magT - mag) > 0.002 || Math.abs(lift - (dragging ? 1 : 0)) > 0.002;
  if (moving || !calm) raf = requestAnimationFrame(step);
}
function kick() { if (!raf && visible && root.isConnected) { last = performance.now(); raf = requestAnimationFrame(step); } }

function local(e) { const s = stage.getBoundingClientRect(); return [e.clientX - s.left, e.clientY - s.top]; }
function touch() { lastInput = performance.now(); }
stage.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'mouse' || dragging) { [tx, ty] = local(e); touch(); kick(); }
});
stage.addEventListener('pointerdown', (e) => {
  [tx, ty] = local(e); touch();
  if (e.target.closest('.fxl-loupe-lens') || e.pointerType === 'mouse') {
    dragging = true;
    try { stage.setPointerCapture(e.pointerId); } catch (err) {}
  }
  kick();
});
const end = () => { if (dragging) { dragging = false; touch(); kick(); } };
stage.addEventListener('pointerup', end);
stage.addEventListener('pointercancel', end);
stage.addEventListener('pointerleave', () => { if (!dragging) { touch(); cur = nearest(tx, ty); if (cur >= 0) [tx, ty] = centers[cur]; kick(); } });

function setZoom(on) {
  zoomed = on;
  zoomBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
  zx.textContent = on ? '2×' : '1.5×';
  kick();
}
zoomBtn.addEventListener('click', () => setZoom(!zoomed));

stage.addEventListener('keydown', (e) => {
  if (!centers.length) return;
  let i = nearest(tx, ty); if (i < 0) i = cur < 0 ? 0 : cur;
  const n = chips.length, c = centers[i];
  let next = null;
  const row = (dir) => {
    let best = null, bd = 1e9;
    centers.forEach((p, k) => {
      const dy = (p[1] - c[1]) * dir;
      if (dy < 4) return;
      const d = dy * 3 + Math.abs(p[0] - c[0]);
      if (d < bd) { bd = d; best = k; }
    });
    return best === null ? i : best;
  };
  if (e.key === 'ArrowRight') next = (i + 1) % n;
  else if (e.key === 'ArrowLeft') next = (i - 1 + n) % n;
  else if (e.key === 'ArrowDown') next = row(1);
  else if (e.key === 'ArrowUp') next = row(-1);
  else if (e.key === 'Home') next = 0;
  else if (e.key === 'End') next = n - 1;
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setZoom(!zoomed); return; }
  else if (e.key === 'Escape') { lastInput = -1e9; tourAt = 0; read.setAttribute('aria-live', 'off'); kick(); return; }
  if (next === null) return;
  e.preventDefault();
  read.setAttribute('aria-live', 'polite');
  cur = next; [tx, ty] = centers[next];
  lastInput = performance.now() + 4000;
  kick();
});

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } measure(); kick(); });
ro.observe(stage);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) kick();
};
document.addEventListener('visibilitychange', onVis);
reduce.addEventListener('change', kick);
measure();
tourAt = performance.now() + 2600;
kick();

