.fxl-pool {
  /* Re-theme with these four; grout, lane and water tint are derived in the canvas. */
  --fxl-pool-tile: oklch(0.87 0.052 170);
  --fxl-pool-lane: oklch(0.52 0.12 36);
  --fxl-pool-ink: oklch(0.29 0.045 195);
  --fxl-pool-paper: oklch(0.975 0.012 95);

  --fxl-pool-grout: color-mix(in oklch, var(--fxl-pool-tile) 78%, var(--fxl-pool-ink));
  --fxl-pool-chip: color-mix(in oklch, var(--fxl-pool-paper) 84%, transparent);
  --fxl-pool-rule: color-mix(in oklch, var(--fxl-pool-ink) 16%, transparent);
  --fxl-pool-muted: color-mix(in oklch, var(--fxl-pool-ink) 62%, var(--fxl-pool-paper));
  --fxl-pool-out: cubic-bezier(.2, .9, .25, 1);
  --fxl-pool-spring: linear(0, 0.1 5%, 0.42 13%, 0.85 24%, 1.06 32%, 1.1 38%, 1.06 46%, 1 58%, 0.99 70%, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4.2;
  min-block-size: 200px;
  max-block-size: 380px;
  display: grid;
  grid-template-areas: "head rain" ". ." "stats stats";
  grid-template-columns: 1fr auto;
  grid-template-rows: auto 1fr auto;
  padding: clamp(10px, 3.6cqi, 16px);
  border-radius: 16px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxl-pool-ink);
  background: var(--fxl-pool-tile);
  box-shadow: inset 0 0 0 1px var(--fxl-pool-rule);
  font: 400 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, dl, dd) { margin: 0; }
}
.fxl-pool .fxl-pool-water,
.fxl-pool .fxl-pool-surface {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
}
.fxl-pool .fxl-pool-water { display: block; z-index: 0; }
.fxl-pool .fxl-pool-probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }
.fxl-pool .fxl-pool-surface {
  z-index: 1;
  cursor: crosshair;
  outline: none;
  touch-action: pan-y;
  border-radius: inherit;
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--fxl-pool-lane), inset 0 0 0 5px color-mix(in oklch, var(--fxl-pool-lane) 22%, transparent); }
}
.fxl-pool .fxl-pool-marker {
  position: absolute;
  z-index: 2;
  left: 0;
  top: 0;
  inline-size: 26px;
  aspect-ratio: 1;
  translate: calc(var(--fxl-pool-mx, 0) * 1px - 50%) calc(var(--fxl-pool-my, 0) * 1px - 50%);
  border-radius: 50%;
  border: 1.5px solid var(--fxl-pool-paper);
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--fxl-pool-ink) 40%, transparent);
  opacity: 0;
  scale: .5;
  pointer-events: none;
  transition: opacity .2s, scale .5s var(--fxl-pool-spring), translate .28s var(--fxl-pool-out);
}
.fxl-pool:has(.fxl-pool-surface:focus-visible) .fxl-pool-marker { opacity: 1; scale: 1; }

.fxl-pool .fxl-pool-head,
.fxl-pool .fxl-pool-stats,
.fxl-pool .fxl-pool-rain { position: relative; z-index: 3; }
.fxl-pool .fxl-pool-head {
  grid-area: head;
  justify-self: start;
  align-self: start;
  display: grid;
  gap: 1px;
  padding: 7px 11px 8px 9px;
  border-radius: 12px;
  background: var(--fxl-pool-chip);
  box-shadow: 0 1px 0 color-mix(in oklch, white 70%, transparent) inset, 0 6px 16px -10px color-mix(in oklch, var(--fxl-pool-ink) 60%, transparent);
  backdrop-filter: blur(6px) saturate(1.3);
  pointer-events: none;
}
.fxl-pool .fxl-pool-place {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: clamp(12px, 4.2cqi, 14px);
  font-weight: 700;
  letter-spacing: -.01em;
}
.fxl-pool .fxl-pool-mark {
  inline-size: 9px;
  block-size: 9px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--fxl-pool-lane) 0 34%, transparent 34% 66%, var(--fxl-pool-lane) 66%);
  box-shadow: 0 0 0 1px var(--fxl-pool-lane);
}
.fxl-pool .fxl-pool-lane {
  padding-inline-start: 15px;
  font: 500 10px/1.2 ui-monospace, Menlo, monospace;
  letter-spacing: .04em;
  color: var(--fxl-pool-muted);
}
.fxl-pool .fxl-pool-rain {
  grid-area: rain;
  align-self: start;
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  block-size: 32px;
  padding: 0 12px 0 9px;
  border: 0;
  border-radius: 999px;
  background: var(--fxl-pool-chip);
  color: var(--fxl-pool-ink);
  box-shadow: 0 1px 0 color-mix(in oklch, white 70%, transparent) inset, 0 6px 16px -10px color-mix(in oklch, var(--fxl-pool-ink) 60%, transparent);
  backdrop-filter: blur(6px) saturate(1.3);
  font: 650 11.5px/1 system-ui, sans-serif;
  cursor: pointer;
  transition: background .25s, color .25s, scale .45s var(--fxl-pool-spring);
  & svg { inline-size: 18px; block-size: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & svg path + path { transition: opacity .25s; }
  &:active { scale: .94; }
  &[aria-pressed="true"] { background: var(--fxl-pool-ink); color: var(--fxl-pool-paper); }
  &[aria-pressed="false"] svg path + path { opacity: .25; }
  &:focus-visible { outline: 2px solid var(--fxl-pool-lane); outline-offset: 2px; }
}
.fxl-pool .fxl-pool-stats {
  grid-area: stats;
  justify-self: start;
  display: flex;
  gap: 2px;
  padding: 4px;
  border-radius: 14px;
  background: var(--fxl-pool-chip);
  backdrop-filter: blur(6px) saturate(1.3);
  box-shadow: 0 1px 0 color-mix(in oklch, white 70%, transparent) inset, 0 6px 16px -10px color-mix(in oklch, var(--fxl-pool-ink) 60%, transparent);
  pointer-events: none;
  & > div {
    display: grid;
    gap: 1px;
    padding: 5px 10px 6px;
    transition: opacity .6s var(--fxl-pool-out), translate .7s var(--fxl-pool-out);
    transition-delay: calc(var(--i) * 60ms + 120ms);
    @starting-style { opacity: 0; translate: 0 6px; }
  }
  & > div + div { border-inline-start: 1px solid var(--fxl-pool-rule); }
  & dt {
    font: 600 9px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxl-pool-muted);
  }
  & dd {
    font-size: 11px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    color: var(--fxl-pool-muted);
  }
  & b {
    font-size: clamp(16px, 6cqi, 21px);
    font-weight: 700;
    letter-spacing: -.03em;
    color: var(--fxl-pool-ink);
    margin-inline-end: 1px;
  }
}
@container (max-width: 300px) {
  .fxl-pool .fxl-pool-rlabel { display: none; }
  .fxl-pool .fxl-pool-rain { padding: 0 7px; }
  .fxl-pool .fxl-pool-stats > div:nth-child(3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .fxl-pool .fxl-pool-marker { transition: opacity .2s; scale: 1; }
  .fxl-pool .fxl-pool-rain { transition: background .25s, color .25s; }
  .fxl-pool .fxl-pool-rain:active { scale: 1; }
  .fxl-pool .fxl-pool-stats > div { transition: none; }
}

