const cv = root.querySelector('.fxl-pool-water');
const surface = root.querySelector('.fxl-pool-surface');
const probe = root.querySelector('.fxl-pool-probe');
const rainBtn = root.querySelector('.fxl-pool-rain');
const countEl = root.querySelector('.fxl-pool-count');
const ctx = cv.getContext('2d', { alpha: false });
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* Hugo Elias' two-buffer wave equation on a coarse grid. Each frame turns the height
   field into a gradient (refraction offset + specular) and a Laplacian (caustic focus),
   bilinearly upsampled and used to sample a tiled floor painted once per size. */
const CELL = 2.5;
let W = 0, H = 0, rs = 1, ow = 0, oh = 0, gw = 0, gh = 0;
let A, B, GX, GY, LP, floor, out, cIdx, cFr, rIdx, rFr;
let raf = 0, last = 0, visible = true, raining = !reduce.matches, nextDrop = 0, ripples = 0, quiet = 0;
let mx = 0, my = 0, lastPt = null;

function rgb(css, fb) {
  const c = document.createElement('canvas'); c.width = c.height = 1;
  const g = c.getContext('2d'); g.fillStyle = fb; g.fillStyle = css; g.fillRect(0, 0, 1, 1);
  const d = g.getImageData(0, 0, 1, 1).data; return [d[0], d[1], d[2]];
}
function cssVar(name, fb) {
  probe.style.color = 'var(' + name + ')';
  return rgb(getComputedStyle(probe).color, fb);
}
function hash(i, j) { const s = Math.sin(i * 127.1 + j * 311.7) * 43758.5453; return s - Math.floor(s); }
const mixc = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const css = (c) => 'rgb(' + c.map((v) => Math.round(v)).join(',') + ')';

function paintFloor() {
  const tile = cssVar('--fxl-pool-tile', '#bfe3d6');
  const lane = cssVar('--fxl-pool-lane', '#a5492b');
  const ink = cssVar('--fxl-pool-ink', '#1f3f42');
  const grout = mixc(tile, ink, 0.2);
  const f = document.createElement('canvas'); f.width = ow; f.height = oh;
  const g = f.getContext('2d');
  g.scale(rs, rs);
  g.fillStyle = css(grout); g.fillRect(0, 0, W, H);
  const t = Math.max(11, Math.min(17, W / 22)), gap = 1.1;
  const laneX = Math.round(W * 0.66 / t), cols = Math.ceil(W / t) + 1, rows = Math.ceil(H / t) + 1;
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const h = hash(i, j);
      let c = mixc(tile, h > 0.5 ? [255, 255, 255] : ink, Math.abs(h - 0.5) * 0.16);
      const inLane = i === laneX && j >= 3;
      const inT = j === 3 && Math.abs(i - laneX) <= 2;
      if (inLane || inT) c = mixc(lane, h > 0.5 ? [255, 255, 255] : ink, Math.abs(h - 0.5) * 0.12);
      g.fillStyle = css(c);
      g.beginPath();
      g.roundRect(i * t + gap / 2, j * t + gap / 2, t - gap, t - gap, 1.6);
      g.fill();
    }
  }
  /* depth mark in mosaic: drawn as text, then re-tiled by clipping to the grout grid */
  g.save();
  g.fillStyle = css(mixc(ink, tile, 0.1));
  g.font = '800 ' + Math.round(t * 2.6) + 'px system-ui, sans-serif';
  g.textBaseline = 'top';
  g.globalAlpha = 0.82;
  g.fillText('1.4 M', t * 1.4, t * 4.2);
  g.restore();
  g.fillStyle = css(grout);
  for (let i = 0; i < cols; i++) g.fillRect(i * t - gap / 2, 0, gap, H);
  for (let j = 0; j < rows; j++) g.fillRect(0, j * t - gap / 2, W, gap);
  /* water column: deeper and cooler toward the far end, sunlit near the coping */
  const wg = g.createLinearGradient(0, 0, 0, H);
  wg.addColorStop(0, 'rgba(255,255,240,0.16)');
  wg.addColorStop(0.55, 'rgba(0,60,70,0)');
  wg.addColorStop(1, 'rgba(0,50,64,0.2)');
  g.fillStyle = wg; g.fillRect(0, 0, W, H);
  floor = g.getImageData(0, 0, ow, oh).data;
}

function build() {
  W = cv.clientWidth; H = cv.clientHeight;
  if (!W || !H) return;
  const dpr = Math.min(2, devicePixelRatio || 1);
  rs = Math.max(0.75, Math.min(dpr, Math.sqrt(170000 / (W * H))));
  ow = Math.round(W * rs); oh = Math.round(H * rs);
  cv.width = ow; cv.height = oh;
  gw = Math.ceil(W / CELL) + 3; gh = Math.ceil(H / CELL) + 3;
  const n = gw * gh;
  A = new Float32Array(n); B = new Float32Array(n);
  GX = new Float32Array(n); GY = new Float32Array(n); LP = new Float32Array(n);
  LP.fill(1);
  cIdx = new Int32Array(ow); cFr = new Float32Array(ow);
  rIdx = new Int32Array(oh); rFr = new Float32Array(oh);
  for (let x = 0; x < ow; x++) { const g = x / rs / CELL + 1; cIdx[x] = g | 0; cFr[x] = g - (g | 0); }
  for (let y = 0; y < oh; y++) { const g = y / rs / CELL + 1; rIdx[y] = g | 0; rFr[y] = g - (g | 0); }
  out = ctx.createImageData(ow, oh);
  paintFloor();
  if (!mx) { mx = W * 0.4; my = H * 0.52; }
  setMarker();
  /* a still frame should already show water: seed three overlapping rings */
  drop(W * 0.3, H * 0.44, 2, 6); drop(W * 0.74, H * 0.64, 1.4, 5); drop(W * 0.55, H * 0.24, 1.1, 5);
  for (let i = 0; i < 26; i++) wave(0.985);
  ripples = 0; countEl.textContent = '0';
  render(performance.now());
}

function drop(x, y, amp, rad) {
  if (!A) return;
  const ci = x / CELL + 1, cj = y / CELL + 1, r = rad;
  for (let j = Math.max(1, Math.floor(cj - r)); j <= Math.min(gh - 2, Math.ceil(cj + r)); j++) {
    for (let i = Math.max(1, Math.floor(ci - r)); i <= Math.min(gw - 2, Math.ceil(ci + r)); i++) {
      const d = Math.hypot(i - ci, j - cj);
      if (d < r) A[j * gw + i] += amp * 0.5 * (1 + Math.cos(Math.PI * d / r));
    }
  }
  quiet = 0;
}
function count() { ripples++; countEl.textContent = ripples.toLocaleString('en-GB'); }

function wave(damp) {
  for (let j = 1; j < gh - 1; j++) {
    for (let i = 1, k = j * gw + 1; i < gw - 1; i++, k++) {
      B[k] = ((A[k - 1] + A[k + 1] + A[k - gw] + A[k + gw]) * 0.5 - B[k]) * damp;
    }
  }
  const t = A; A = B; B = t;
}

function render(now) {
  let energy = 0;
  const t = (now || 0) * 0.00055, sc = CELL / 2.5, net = reduce.matches ? 0.12 : 0.3;
  for (let j = 1; j < gh - 1; j++) {
    for (let i = 1, k = j * gw + 1; i < gw - 1; i++, k++) {
      const c = A[k];
      const gx = A[k + 1] - A[k - 1], gy = A[k + gw] - A[k - gw];
      GX[k] = gx; GY[k] = gy;
      /* sunlight net on the floor: where three drifting sine fronts cancel, light focuses.
         The ripple gradient bends the net, so wakes visibly drag the caustics along. */
      const u = (i + gx * 6) * sc, v = (j + gy * 6) * sc;
      const z = Math.sin(u * 0.23 + v * 0.11 + t * 1.3) + Math.sin(-u * 0.08 + v * 0.25 - t) + Math.sin(u * 0.17 - v * 0.2 + t * 0.8);
      let q = 1 - Math.abs(z) * 0.5; if (q < 0) q = 0;
      q *= q; q *= q; q *= q;
      LP[k] = 1 - (A[k - 1] + A[k + 1] + A[k - gw] + A[k + gw] - 4 * c) * 1.7 + q * net;
      energy += c < 0 ? -c : c;
    }
  }
  const d = out.data, f = floor, K = 9 * rs;
  for (let y = 0; y < oh; y++) {
    const j = rIdx[y], fy = rFr[y], row = j * gw;
    for (let x = 0; x < ow; x++) {
      const i = cIdx[x], fx = cFr[x];
      const k = row + i, k2 = k + gw;
      const w00 = (1 - fx) * (1 - fy), w10 = fx * (1 - fy), w01 = (1 - fx) * fy, w11 = fx * fy;
      const gx = GX[k] * w00 + GX[k + 1] * w10 + GX[k2] * w01 + GX[k2 + 1] * w11;
      const gy = GY[k] * w00 + GY[k + 1] * w10 + GY[k2] * w01 + GY[k2 + 1] * w11;
      const lp = LP[k] * w00 + LP[k + 1] * w10 + LP[k2] * w01 + LP[k2 + 1] * w11;
      let sx = (x + gx * K) | 0, sy = (y + gy * K) | 0;
      if (sx < 0) sx = 0; else if (sx >= ow) sx = ow - 1;
      if (sy < 0) sy = 0; else if (sy >= oh) sy = oh - 1;
      const s = (sy * ow + sx) * 4, o = (y * ow + x) * 4;
      let b = lp;                                               /* converging light brightens */
      if (b < 0.72) b = 0.72; else if (b > 1.6) b = 1.6;
      let sp = -(gx * 0.55 + gy * 0.83);                         /* sun up and to the left */
      sp = sp > 0 ? sp * sp * 520 : 0;
      if (sp > 90) sp = 90;
      d[o] = f[s] * b + sp; d[o + 1] = f[s + 1] * b + sp; d[o + 2] = f[s + 2] * b + sp; d[o + 3] = 255;
    }
  }
  ctx.putImageData(out, 0, 0);
  return energy / (gw * gh);
}

function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible || !A) return;
  const dt = Math.min(0.05, (now - last) / 1000 || 0.016); last = now;
  const calm = reduce.matches;
  if (raining && !calm && now > nextDrop) {
    drop(Math.random() * W, Math.random() * H, 0.35 + Math.random() * 0.8, 3.2 + Math.random() * 2.2);
    count();
    nextDrop = now + 120 + Math.random() * Math.random() * 900;
  }
  if (!calm) {   /* a breath of wind keeps the surface from ever going glassy */
    for (let n = 0; n < 2; n++) drop(Math.random() * W, Math.random() * H, 0.022, 3);
  }
  const damp = calm ? 0.955 : 0.986;
  wave(damp); wave(damp);
  const e = render(now);
  quiet = e < 0.0006 ? quiet + dt : 0;
  if (quiet < 0.5 || (!calm && raining) || !calm) raf = requestAnimationFrame(step);
}
function kick() { if (!raf && visible && root.isConnected) { last = performance.now(); raf = requestAnimationFrame(step); } }

function local(e) { const r = cv.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }
function wake(x0, y0, x1, y1, amp) {
  const dist = Math.hypot(x1 - x0, y1 - y0), n = Math.max(1, Math.ceil(dist / CELL));
  for (let i = 1; i <= n; i++) drop(x0 + (x1 - x0) * i / n, y0 + (y1 - y0) * i / n, amp * 0.6, 3.4);
}
surface.addEventListener('pointermove', (e) => {
  const [x, y] = local(e);
  if (lastPt) {
    const sp = Math.hypot(x - lastPt[0], y - lastPt[1]);
    wake(lastPt[0], lastPt[1], x, y, Math.min(0.45, 0.04 + sp * 0.012) * (e.buttons ? 1.6 : 1));
  }
  lastPt = [x, y];
  kick();
});
surface.addEventListener('pointerleave', () => { lastPt = null; });
surface.addEventListener('pointerdown', (e) => {
  const [x, y] = local(e);
  drop(x, y, reduce.matches ? 0.9 : 2.4, 6); count();
  lastPt = [x, y];
  kick();
});

function setMarker() { root.style.setProperty('--fxl-pool-mx', mx.toFixed(1)); root.style.setProperty('--fxl-pool-my', my.toFixed(1)); }
function setRain(on) {
  raining = on;
  rainBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
  nextDrop = 0; kick();
}
rainBtn.addEventListener('click', () => setRain(!raining));
surface.addEventListener('keydown', (e) => {
  const s = Math.max(10, W * 0.05);
  const moves = { ArrowLeft: [-s, 0], ArrowRight: [s, 0], ArrowUp: [0, -s], ArrowDown: [0, s] };
  if (moves[e.key]) {
    e.preventDefault();
    const nx = Math.max(8, Math.min(W - 8, mx + moves[e.key][0])), ny = Math.max(8, Math.min(H - 8, my + moves[e.key][1]));
    wake(mx, my, nx, ny, 0.5);
    mx = nx; my = ny; setMarker(); kick();
  } else if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault(); drop(mx, my, reduce.matches ? 0.9 : 2.4, 6); count(); kick();
  } else if (e.key === 'r' || e.key === 'R') {
    setRain(!raining);
  }
});

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } build(); kick(); });
ro.observe(cv);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) kick();
};
document.addEventListener('visibilitychange', onVis);
reduce.addEventListener('change', () => { setRain(!reduce.matches); });
if (reduce.matches) rainBtn.setAttribute('aria-pressed', 'false');
build();
kick();

