.fxl-steam {
  /* Re-theme with these four. The scene is painted from them in the canvas. */
  --fxl-steam-dusk: oklch(0.3 0.035 232);
  --fxl-steam-glow: oklch(0.74 0.14 62);
  --fxl-steam-fog: oklch(0.82 0.018 225);
  --fxl-steam-ink: oklch(0.97 0.008 90);

  --fxl-steam-muted: color-mix(in oklch, var(--fxl-steam-ink) 66%, var(--fxl-steam-dusk));
  --fxl-steam-chip: color-mix(in oklch, var(--fxl-steam-dusk) 58%, transparent);
  --fxl-steam-rule: color-mix(in oklch, var(--fxl-steam-ink) 18%, transparent);
  --fxl-steam-out: cubic-bezier(.22, 1, .36, 1);
  --fxl-steam-spring: linear(0, 0.12 5%, 0.48 14%, 0.9 25%, 1.07 33%, 1.09 39%, 1.04 48%, 0.99 62%, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
