const cv = root.querySelector('.fxl-steam-cv');
const glass = root.querySelector('.fxl-steam-glass');
const probe = root.querySelector('.fxl-steam-probe');
const pctEl = root.querySelector('.fxl-steam-pct');
const breatheBtn = root.querySelector('.fxl-steam-breathe');
const ctx = cv.getContext('2d');
const MOPT = { willReadFrequently: true };
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* Three canvases: a sharp street scene, a pre-blurred "fogged" copy of it, and a small
   alpha mask of where the condensation is. Wiping stamps a soft brush into the mask
   with destination-out; the fog grows back by drawing a blotchy seed into it each frame.
   Beads that run down the pane wipe their own streaks and show the street upside down. */
let W = 0, H = 0, dpr = 1, MS = 3;
let scene, fog, mask, mctx, tmp, tctx, seed, brush, beads = [];
let raf = 0, last = 0, visible = true, frame = 0, lastInput = -1e9, idleAt = 0;
let fingerX = 0, fingerY = 0, ghost = null, breath = 0, pctShown = -1;

const mk = (w, h) => { const c = document.createElement('canvas'); c.width = Math.max(1, w); c.height = Math.max(1, h); return c; };
function col(name, fb) {
  probe.style.color = 'var(' + name + ')';
  const c = mk(1, 1), g = c.getContext('2d');
  g.fillStyle = fb; g.fillStyle = getComputedStyle(probe).color; g.fillRect(0, 0, 1, 1);
  const d = g.getImageData(0, 0, 1, 1).data; return [d[0], d[1], d[2]];
}
const rgba = (c, a) => 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a + ')';
const mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
let seedN = 7;
function rnd() { seedN = (seedN * 16807) % 2147483647; return (seedN - 1) / 2147483646; }

function paintScene() {
  const dusk = col('--fxl-steam-dusk', '#25323d'), glow = col('--fxl-steam-glow', '#e59a4c');
  const fogc = col('--fxl-steam-fog', '#c8d2da');
  seedN = 11;
  scene = mk(W * dpr, H * dpr);
  const g = scene.getContext('2d');
  g.scale(dpr, dpr);
  const hz = H * 0.66;
  const sky = g.createLinearGradient(0, 0, 0, hz);
  sky.addColorStop(0, rgba(mix(dusk, [0, 0, 0], 0.25), 1));
  sky.addColorStop(0.55, rgba(mix(dusk, fogc, 0.18), 1));
  sky.addColorStop(1, rgba(mix(dusk, glow, 0.55), 1));
  g.fillStyle = sky; g.fillRect(0, 0, W, H);
  /* two rows of blocks; the far row is hazier */
  for (const row of [{ y0: 0.28, y1: 0.5, t: 0.42, lit: 0.3 }, { y0: 0.12, y1: 0.4, t: 0.2, lit: 0.42 }]) {
    let x = -10;
    while (x < W + 10) {
      const bw = W * (0.07 + rnd() * 0.12), top = H * (row.y0 + rnd() * (row.y1 - row.y0));
      g.fillStyle = rgba(mix(mix(dusk, [0, 0, 0], 0.45), fogc, row.t), 1);
      g.fillRect(x, top, bw - 1, hz - top + 2);
      const ww = 2.4, wh = 3.4;
      for (let wy = top + 6; wy < hz - 8; wy += 8) {
        for (let wx = x + 4; wx < x + bw - 6; wx += 6) {
          if (rnd() < row.lit) {
            const warm = rnd() < 0.78;
            g.fillStyle = rgba(warm ? mix(glow, [255, 236, 190], 0.45) : [200, 222, 236], 0.5 + rnd() * 0.5);
            g.fillRect(wx, wy, ww, wh);
          }
        }
      }
      x += bw;
    }
  }
  /* neon over the noodle bar */
  g.save();
  g.globalCompositeOperation = 'lighter';
  g.font = '700 ' + Math.round(W * 0.05) + 'px system-ui, sans-serif';
  g.shadowColor = 'rgba(255,80,90,0.9)'; g.shadowBlur = 10;
  g.fillStyle = 'rgba(255,150,150,0.95)';
  g.fillText('NOODLES', W * 0.07, hz - H * 0.17);
  g.restore();
  /* wet street */
  const st = g.createLinearGradient(0, hz, 0, H);
  st.addColorStop(0, rgba(mix(dusk, [0, 0, 0], 0.5), 1));
  st.addColorStop(1, rgba(mix(dusk, [0, 0, 0], 0.7), 1));
  g.fillStyle = st; g.fillRect(0, hz, W, H - hz);
  g.globalCompositeOperation = 'lighter';
  const lamp = (x, y, r, c, a) => {
    const rg = g.createRadialGradient(x, y, 0, x, y, r);
    rg.addColorStop(0, rgba(c, a)); rg.addColorStop(0.25, rgba(c, a * 0.35)); rg.addColorStop(1, rgba(c, 0));
    g.fillStyle = rg; g.fillRect(x - r, y - r, r * 2, r * 2);
    /* the reflection smeared down the wet asphalt */
    const rf = g.createLinearGradient(0, hz, 0, H);
    rf.addColorStop(0, rgba(c, a * 0.35)); rf.addColorStop(1, rgba(c, 0));
    g.fillStyle = rf; g.fillRect(x - r * 0.12, hz, r * 0.24, H - hz);
  };
  const sodium = mix(glow, [255, 200, 120], 0.3);
  for (const fx of [0.2, 0.52, 0.86]) {
    g.globalCompositeOperation = 'source-over';
    g.strokeStyle = rgba(mix(dusk, [0, 0, 0], 0.6), 1); g.lineWidth = 2;
    g.beginPath(); g.moveTo(W * fx, hz + 4); g.lineTo(W * fx, H * 0.38); g.lineTo(W * fx + 9, H * 0.37); g.stroke();
    g.globalCompositeOperation = 'lighter';
    lamp(W * fx + 9, H * 0.38, W * 0.12, sodium, 0.9);
  }
  for (const [fx, fy, c] of [[0.34, 0.8, [255, 60, 50]], [0.37, 0.8, [255, 60, 50]], [0.7, 0.84, [255, 248, 230]], [0.75, 0.84, [255, 248, 230]], [0.1, 0.77, [255, 70, 60]], [0.94, 0.62, [90, 230, 140]]]) {
    lamp(W * fx, H * fy, W * 0.045, c, 1);
  }
  g.globalCompositeOperation = 'source-over';
  /* tram-stop pole and plate, close to the glass */
  g.fillStyle = rgba(mix(dusk, [0, 0, 0], 0.75), 1);
  g.fillRect(W * 0.62, H * 0.42, 3, H * 0.6);
  g.fillStyle = rgba(glow, 1);
  g.fillRect(W * 0.62 - 7, H * 0.42, 17, 12);
}

function paintFog() {
  const fogc = col('--fxl-steam-fog', '#c8d2da');
  fog = mk(scene.width, scene.height);
  const g = fog.getContext('2d');
  /* cheap wide blur: down to 1/14, back up twice with smoothing */
  const s1 = mk(Math.ceil(scene.width / 14), Math.ceil(scene.height / 14));
  const s1g = s1.getContext('2d');
  s1g.imageSmoothingQuality = 'high';
  s1g.drawImage(scene, 0, 0, s1.width, s1.height);
  const s2 = mk(Math.ceil(scene.width / 4), Math.ceil(scene.height / 4));
  const s2g = s2.getContext('2d');
  s2g.imageSmoothingQuality = 'high';
  s2g.drawImage(s1, 0, 0, s2.width, s2.height);
  g.imageSmoothingQuality = 'high';
  g.drawImage(s2, 0, 0, fog.width, fog.height);
  /* milk it: the scattering lifts the darks more than the lights */
  g.fillStyle = rgba(fogc, 0.34); g.fillRect(0, 0, fog.width, fog.height);
  g.globalCompositeOperation = 'lighter';
  g.drawImage(s2, 0, 0, fog.width, fog.height);
  g.globalCompositeOperation = 'source-over';
  /* condensation grain: thousands of micro-beads, each a lighter speck with a dark lip */
  seedN = 29;
  const n = Math.round(W * H / 22);
  for (let i = 0; i < n; i++) {
    const x = rnd() * fog.width, y = rnd() * fog.height, r = (0.4 + rnd() * rnd() * 1.6) * dpr;
    g.fillStyle = 'rgba(255,255,255,' + (0.05 + rnd() * 0.1) + ')';
    g.beginPath(); g.arc(x, y, r, 0, 6.2832); g.fill();
    g.fillStyle = 'rgba(0,10,20,' + (0.04 + rnd() * 0.05) + ')';
    g.beginPath(); g.arc(x + r * 0.3, y + r * 0.4, r * 0.7, 0, 6.2832); g.fill();
  }
}

function build() {
  W = cv.clientWidth; H = cv.clientHeight;
  if (!W || !H) return;
  dpr = Math.min(2, devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  paintScene(); paintFog();
  const mw = Math.ceil(W / MS), mh = Math.ceil(H / MS);
  const old = mask;
  mask = mk(mw, mh); mctx = mask.getContext('2d', MOPT);
  /* keep whatever has been wiped when the pane is resized */
  if (old) mctx.drawImage(old, 0, 0, mw, mh);
  else { mctx.fillStyle = '#fff'; mctx.fillRect(0, 0, mw, mh); }
  tmp = mk(cv.width, cv.height); tctx = tmp.getContext('2d');
  /* blotchy seed so the fog creeps back unevenly, from the cold edges first */
  seed = mk(mw, mh);
  const sg = seed.getContext('2d');
  const sm = mk(Math.ceil(mw / 9), Math.ceil(mh / 9)), smg = sm.getContext('2d');
  seedN = 5;
  for (let y = 0; y < sm.height; y++) for (let x = 0; x < sm.width; x++) {
    const ex = Math.min(x, sm.width - 1 - x), ey = Math.min(y, sm.height - 1 - y);
    smg.fillStyle = 'rgba(255,255,255,' + Math.min(1, 0.35 + rnd() * 0.45 + (ex + ey < 2 ? 0.3 : 0)) + ')';
    smg.fillRect(x, y, 1, 1);
  }
  sg.imageSmoothingQuality = 'high';
  sg.drawImage(sm, 0, 0, mw, mh);
  const br = Math.ceil(18 / MS);
  brush = mk(br * 2, br * 2);
  const bg = brush.getContext('2d'), rg = bg.createRadialGradient(br, br, 0, br, br, br);
  rg.addColorStop(0, 'rgba(0,0,0,1)'); rg.addColorStop(0.55, 'rgba(0,0,0,0.85)'); rg.addColorStop(1, 'rgba(0,0,0,0)');
  bg.fillStyle = rg; bg.fillRect(0, 0, br * 2, br * 2);
  if (!fingerX) { fingerX = W * 0.5; fingerY = H * 0.52; setFinger(); }
  if (!old) startGhost(0);
  draw();
}

function stamp(x, y, scale, strength) {
  mctx.globalCompositeOperation = 'destination-out';
  mctx.globalAlpha = strength;
  const s = brush.width * scale;
  mctx.drawImage(brush, x / MS - s / 2, y / MS - s / 2, s, s);
  mctx.globalAlpha = 1;
  mctx.globalCompositeOperation = 'source-over';
}
function wipe(x0, y0, x1, y1, scale) {
  const d = Math.hypot(x1 - x0, y1 - y0), n = Math.max(1, Math.ceil(d / 3));
  for (let i = 1; i <= n; i++) stamp(x0 + (x1 - x0) * i / n, y0 + (y1 - y0) * i / n, scale || 1, 0.55);
  /* water pushed to the edge of the finger gathers into beads */
  if (beads.length < 36 && Math.random() < Math.min(0.45, d * 0.018)) {
    const a = Math.random() * 6.2832, r = 15 + Math.random() * 6;
    beads.push({ x: x1 + Math.cos(a) * r, y: y1 + Math.abs(Math.sin(a)) * r, r: 1.2 + Math.random() * 1.9, v: 0, hold: 0.2 + Math.random() * 1.6, run: false });
  }
}

/* ghost finger: on mount, and whenever the pane has fogged over and been left alone */
const GHOSTS = [
  [[0.18, 0.36], [0.78, 0.33], [0.2, 0.47], [0.8, 0.45], [0.24, 0.6], [0.74, 0.58]],
  [[0.5, 0.48], [0.56, 0.44], [0.6, 0.5], [0.52, 0.58], [0.42, 0.52], [0.44, 0.4], [0.58, 0.34], [0.7, 0.46], [0.64, 0.64], [0.46, 0.68], [0.32, 0.56], [0.34, 0.38]],
  [[0.14, 0.62], [0.32, 0.4], [0.5, 0.58], [0.68, 0.38], [0.86, 0.56]],
];
let ghostK = 0;
function startGhost(delay) {
  ghost = { pts: GHOSTS[ghostK % GHOSTS.length], t: -delay, dur: 1.5 };
  ghostK++;
}
function runGhost(dt) {
  if (!ghost) return;
  if (reduce.matches) {                       /* calm: the pane is simply already wiped */
    const p = ghost.pts;
    for (let pass = 0; pass < 3; pass++) for (let i = 0; i < p.length - 1; i++) wipe(p[i][0] * W, p[i][1] * H, p[i + 1][0] * W, p[i + 1][1] * H, 1.15);
    beads = []; ghost = null; return;
  }
  const prev = ghost.t;
  ghost.t += dt;
  if (ghost.t < 0) return;
  const p = ghost.pts, n = p.length - 1;
  const at = (t) => {
    const u = Math.max(0, Math.min(1, t / ghost.dur)) * n, i = Math.min(n - 1, Math.floor(u)), f = u - i;
    const e = f * f * (3 - 2 * f);
    return [(p[i][0] + (p[i + 1][0] - p[i][0]) * e) * W, (p[i][1] + (p[i + 1][1] - p[i][1]) * e) * H];
  };
  const a = at(Math.max(0, prev)), b = at(ghost.t);
  wipe(a[0], a[1], b[0], b[1], 1.15);
  if (ghost.t >= ghost.dur) ghost = null;
}

function beadsStep(dt) {
  for (let i = beads.length - 1; i >= 0; i--) {
    const b = beads[i];
    if (!b.run) {
      b.hold -= dt;
      b.r += dt * 0.25;                       /* keeps collecting condensation */
      if (b.hold <= 0 && b.r > 2.2) b.run = true;
      continue;
    }
    /* stick-slip: speed tracks mass, with random snags on the glass */
    b.v += (b.r * 26 - b.v) * Math.min(1, dt * 4);
    if (Math.random() < dt * 1.6) b.v *= 0.15;
    const ny = b.y + b.v * dt;
    for (let y = b.y; y < ny; y += 1.2) stamp(b.x, y, b.r / 15, 0.6);
    b.x += (Math.random() - 0.5) * 0.6;
    b.y = ny;
    if (Math.random() < dt * 0.9 && b.r > 1.6) {     /* leaves a smaller bead behind */
      b.r -= 0.25;
      if (beads.length < 60) beads.push({ x: b.x, y: b.y - 2, r: 0.6 + Math.random() * 0.45, v: 0, hold: 1e9, run: false });
    }
    if (b.y > H + 6) beads.splice(i, 1);
  }
}

function drawBead(b) {
  const r = b.r;
  ctx.save();
  ctx.beginPath(); ctx.arc(b.x, b.y, r, 0, 6.2832); ctx.clip();
  /* a bead is a fisheye: the street, wide and upside down */
  const sw = r * 9;
  ctx.translate(b.x, b.y); ctx.scale(-1, -1);
  ctx.drawImage(scene, (b.x - sw / 2) * dpr, (b.y - sw / 2) * dpr, sw * dpr, sw * dpr, -r, -r, r * 2, r * 2);
  ctx.restore();
  ctx.lineWidth = Math.max(0.5, r * 0.22);
  ctx.strokeStyle = 'rgba(6,12,20,0.32)';
  ctx.beginPath(); ctx.arc(b.x, b.y, r * 0.9, 3.6, 5.8); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,240,220,0.32)';
  ctx.beginPath(); ctx.arc(b.x, b.y, r * 0.8, 0.5, 2.6); ctx.stroke();
  ctx.fillStyle = 'rgba(255,255,255,0.8)';
  ctx.beginPath(); ctx.arc(b.x - r * 0.32, b.y - r * 0.38, Math.max(0.4, r * 0.2), 0, 6.2832); ctx.fill();
}

function draw() {
  if (!scene) return;
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalCompositeOperation = 'source-over';
  ctx.drawImage(scene, 0, 0);
  tctx.globalCompositeOperation = 'source-over';
  tctx.clearRect(0, 0, tmp.width, tmp.height);
  tctx.drawImage(fog, 0, 0);
  tctx.globalCompositeOperation = 'destination-in';
  tctx.imageSmoothingQuality = 'high';
  tctx.drawImage(mask, 0, 0, tmp.width, tmp.height);
  ctx.drawImage(tmp, 0, 0);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
