}

function measureClear() {
  const d = mctx.getImageData(0, 0, mask.width, mask.height).data;
  let s = 0;
  for (let i = 3; i < d.length; i += 16) s += d[i];
  const pct = Math.round(100 - s / (d.length / 16) / 2.55);
  if (pct !== pctShown) { pctShown = pct; pctEl.textContent = Math.max(0, pct); }
