}

function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible || !scene) return;
  const dt = Math.min(0.05, (now - last) / 1000 || 0.016); last = now;
  const calm = reduce.matches;
  runGhost(dt);
  /* fog creeps back; a breath brings it back at once */
  const rate = breath > 0 ? 2.6 : calm ? 0.02 : 0.055;
  breath = Math.max(0, breath - dt);
  mctx.globalAlpha = Math.min(1, rate * dt);
  mctx.drawImage(seed, 0, 0);
  mctx.globalAlpha = 1;
  if (!calm) beadsStep(dt);
  else for (const b of beads) b.run = false;
  if (breath > 0) beads = beads.filter(() => Math.random() > dt * 2.5);
  draw();
  frame++;
  let clear = pctShown;
  if (frame % 10 === 1) clear = measureClear();
  if (!calm && !ghost && clear <= 1 && now - lastInput > 4000 && now > idleAt) { startGhost(0.8); idleAt = now + 9000; }
  const busy = ghost || breath > 0 || clear > 0 || beads.some((b) => b.run);
  if (busy || !calm) raf = requestAnimationFrame(step);
}
function kick() { if (!raf && visible && root.isConnected) { last = performance.now(); raf = requestAnimationFrame(step); } }

let lastPt = null;
function local(e) { const r = cv.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; }
glass.addEventListener('pointerdown', (e) => {
  lastPt = local(e); ghost = null; lastInput = performance.now();
  stamp(lastPt[0], lastPt[1], 1, 0.6);
