const lift = () => { lastPt = null; };
glass.addEventListener('pointerup', lift);
glass.addEventListener('pointercancel', lift);

function setFinger() { root.style.setProperty('--fxl-steam-fx', fingerX.toFixed(1)); root.style.setProperty('--fxl-steam-fy', fingerY.toFixed(1)); }
function breathe() {
  breath = 0.9; lastInput = performance.now(); ghost = null;
  root.removeAttribute('data-breath'); void root.offsetWidth; root.setAttribute('data-breath', '');
  kick();
}
breatheBtn.addEventListener('click', breathe);
glass.addEventListener('keydown', (e) => {
  const s = Math.max(12, W * 0.06);
  const mv = { ArrowLeft: [-s, 0], ArrowRight: [s, 0], ArrowUp: [0, -s], ArrowDown: [0, s] }[e.key];
  if (mv) {
    e.preventDefault();
    const nx = Math.max(10, Math.min(W - 10, fingerX + mv[0])), ny = Math.max(10, Math.min(H - 10, fingerY + mv[1]));
    wipe(fingerX, fingerY, nx, ny, 1);
    fingerX = nx; fingerY = ny; setFinger(); lastInput = performance.now(); kick();
  } else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); breathe(); }
});

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } build(); kick(); });
ro.observe(cv);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) kick();
};
document.addEventListener('visibilitychange', onVis);
reduce.addEventListener('change', kick);
build();
kick();

