@property --fxl-sampler-sheen {
  syntax: '<percentage>';
  inherits: false;
  initial-value: -30%;
}
.fxl-sampler {
  /* Re-theme with these four; the bathroom behind the glass is drawn from them. */
  --fxl-sampler-wall: oklch(0.955 0.016 82);
  --fxl-sampler-ink: oklch(0.27 0.03 160);
  --fxl-sampler-brass: oklch(0.7 0.11 78);
  --fxl-sampler-clay: oklch(0.6 0.13 38);

  --fxl-sampler-tile: color-mix(in oklch, var(--fxl-sampler-wall) 70%, oklch(0.78 0.06 165));
  --fxl-sampler-muted: color-mix(in oklch, var(--fxl-sampler-ink) 58%, var(--fxl-sampler-wall));
  --fxl-sampler-rule: color-mix(in oklch, var(--fxl-sampler-ink) 13%, transparent);
  --fxl-sampler-out: cubic-bezier(.2, .9, .2, 1);
  --fxl-sampler-spring: linear(0, 0.1 5%, 0.45 14%, 0.88 25%, 1.06 33%, 1.08 39%, 1.04 47%, 0.99 62%, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  display: grid;
  grid-template-areas: "head" "scene" "opts" "foot";
  gap: clamp(9px, 3cqi, 12px);
  padding: clamp(12px, 4.2cqi, 18px);
  border-radius: 16px;
  color: var(--fxl-sampler-ink);
  background: var(--fxl-sampler-wall);
  box-shadow: inset 0 0 0 1px var(--fxl-sampler-rule);
  font: 400 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3) { margin: 0; }
}
.fxl-sampler .fxl-sampler-defs { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }

.fxl-sampler .fxl-sampler-head { grid-area: head; display: grid; gap: 2px; }
.fxl-sampler .fxl-sampler-eyebrow {
  font: 600 9.5px/1.2 ui-monospace, Menlo, monospace;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--fxl-sampler-muted);
}
.fxl-sampler .fxl-sampler-title {
  font-size: clamp(14px, 5cqi, 18px);
  font-weight: 650;
  letter-spacing: -.02em;
  text-wrap: balance;
}

.fxl-sampler .fxl-sampler-scene {
  grid-area: scene;
  position: relative;
  aspect-ratio: 16 / 9;
  border-radius: 10px;
  overflow: hidden;
  isolation: isolate;
  cursor: ew-resize;
  touch-action: pan-y;
  box-shadow: inset 0 0 0 1px var(--fxl-sampler-rule), 0 1px 0 color-mix(in oklch, white 60%, transparent);
}
.fxl-sampler .fxl-sampler-base,
.fxl-sampler .fxl-sampler-pane { position: absolute; inset: 0; }
.fxl-sampler .fxl-sampler-art { display: block; inline-size: 100%; block-size: 100%; }
.fxl-sampler .fxl-sampler-pane {
  clip-path: inset(0 0 0 calc(var(--fxl-sampler-door) * 1%));
  pointer-events: none;
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    background: color-mix(in oklch, oklch(0.88 0.05 175) 14%, transparent);
  }
}
.fxl-sampler .fxl-sampler-pane--b { visibility: hidden; }
.fxl-sampler .fxl-sampler-sheen {
  position: absolute;
  inset: 0;
  clip-path: inset(0 0 0 calc(var(--fxl-sampler-door) * 1%));
  pointer-events: none;
  background: linear-gradient(104deg, transparent calc(var(--fxl-sampler-sheen) - 14%), color-mix(in oklch, white 34%, transparent) var(--fxl-sampler-sheen), transparent calc(var(--fxl-sampler-sheen) + 9%));
  mix-blend-mode: soft-light;
  animation: fxl-sampler-sweep 7s cubic-bezier(.45, 0, .2, 1) 1.2s infinite;
}
@keyframes fxl-sampler-sweep {
  0% { --fxl-sampler-sheen: -30%; }
  55%, 100% { --fxl-sampler-sheen: 135%; }
}
.fxl-sampler .fxl-sampler-frame {
  position: absolute;
  inset: 0 0 0 calc(var(--fxl-sampler-door) * 1%);
  pointer-events: none;
  border-block: 3px solid var(--fxl-sampler-brass);
  border-inline-start: 0;
  box-shadow: inset 0 1px 0 color-mix(in oklch, white 50%, transparent);
}
.fxl-sampler .fxl-sampler-handle {
  position: absolute;
  inset-block: 0;
  left: calc(var(--fxl-sampler-door) * 1%);
  inline-size: 30px;
  translate: -50% 0;
  display: grid;
  place-items: center;
  outline: none;
  cursor: ew-resize;
  touch-action: none;
  &::before {
    content: "";
    position: absolute;
    inset-block: 0;
    left: calc(50% - 3px);
    inline-size: 6px;
    background: linear-gradient(90deg, color-mix(in oklch, var(--fxl-sampler-brass) 70%, black), var(--fxl-sampler-brass) 35%, color-mix(in oklch, var(--fxl-sampler-brass) 50%, white) 55%, color-mix(in oklch, var(--fxl-sampler-brass) 80%, black));
    box-shadow: 0 0 10px color-mix(in oklch, var(--fxl-sampler-ink) 30%, transparent);
  }
}
.fxl-sampler .fxl-sampler-grip {
  position: relative;
  inline-size: 12px;
  block-size: 44px;
  border-radius: 6px;
  background: linear-gradient(90deg, color-mix(in oklch, var(--fxl-sampler-brass) 60%, black), color-mix(in oklch, var(--fxl-sampler-brass) 40%, white) 45%, var(--fxl-sampler-brass));
  box-shadow: 0 3px 8px -2px color-mix(in oklch, var(--fxl-sampler-ink) 55%, transparent), inset 0 0 0 1px color-mix(in oklch, var(--fxl-sampler-brass) 50%, black);
  transition: scale .45s var(--fxl-sampler-spring), block-size .45s var(--fxl-sampler-spring);
}
.fxl-sampler .fxl-sampler-handle:hover .fxl-sampler-grip,
.fxl-sampler .fxl-sampler-scene[data-drag] .fxl-sampler-grip { scale: 1.12; block-size: 52px; }
.fxl-sampler .fxl-sampler-handle:focus-visible .fxl-sampler-grip { outline: 2px solid var(--fxl-sampler-ink); outline-offset: 3px; }

/* the art */
.fxl-sampler .fxl-sampler-a-wall { fill: var(--fxl-sampler-tile); }
.fxl-sampler .fxl-sampler-a-grout { fill: none; stroke: color-mix(in oklch, var(--fxl-sampler-tile) 72%, var(--fxl-sampler-ink)); stroke-width: 1.1; }
.fxl-sampler .fxl-sampler-a-lamp { fill: color-mix(in oklch, var(--fxl-sampler-brass) 45%, white); }
.fxl-sampler .fxl-sampler-a-lampcore { fill: color-mix(in oklch, var(--fxl-sampler-brass) 30%, oklch(0.97 0.08 95)); }
.fxl-sampler .fxl-sampler-a-floor { fill: color-mix(in oklch, var(--fxl-sampler-ink) 72%, var(--fxl-sampler-wall)); }
.fxl-sampler .fxl-sampler-a-leaf { fill: color-mix(in oklch, var(--fxl-sampler-ink) 55%, oklch(0.55 0.13 150)); }
.fxl-sampler .fxl-sampler-a-leaf2 { fill: color-mix(in oklch, var(--fxl-sampler-ink) 30%, oklch(0.62 0.14 145)); }
.fxl-sampler .fxl-sampler-a-pot { fill: var(--fxl-sampler-clay); }
.fxl-sampler .fxl-sampler-a-figure { fill: color-mix(in oklch, var(--fxl-sampler-clay) 70%, var(--fxl-sampler-ink)); }
.fxl-sampler .fxl-sampler-a-rail { fill: var(--fxl-sampler-brass); }
.fxl-sampler .fxl-sampler-a-towel rect { fill: color-mix(in oklch, var(--fxl-sampler-wall) 80%, white); }
.fxl-sampler .fxl-sampler-a-stripe { fill: color-mix(in oklch, var(--fxl-sampler-ink) 80%, oklch(0.5 0.08 220)); }
.fxl-sampler .fxl-sampler-a-stripe2 { fill: var(--fxl-sampler-brass); }

.fxl-sampler .fxl-sampler-opts {
  grid-area: opts;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
}
@container (min-width: 470px) { .fxl-sampler .fxl-sampler-opts { grid-template-columns: repeat(6, minmax(0, 1fr)); } }
.fxl-sampler .fxl-sampler-opt {
  appearance: none;
  display: flex;
  align-items: center;
  gap: 6px;
  min-inline-size: 0;
  block-size: 32px;
  padding: 0 6px 0 5px;
  border: 1px solid var(--fxl-sampler-rule);
  border-radius: 9px;
  background: color-mix(in oklch, var(--fxl-sampler-wall) 60%, white);
  color: inherit;
  font: 600 11px/1 system-ui, sans-serif;
  cursor: pointer;
  transition: border-color .2s, background .2s, scale .4s var(--fxl-sampler-spring), opacity .5s var(--fxl-sampler-out), translate .6s var(--fxl-sampler-out);
  transition-delay: 0s, 0s, 0s, calc(var(--i) * 40ms + 100ms), calc(var(--i) * 40ms + 100ms);
  @starting-style { opacity: 0; translate: 0 6px; }
  &:hover { border-color: color-mix(in oklch, var(--fxl-sampler-ink) 32%, transparent); }
  &:active { scale: .96; }
  &[aria-checked="true"] {
    border-color: var(--fxl-sampler-ink);
    background: var(--fxl-sampler-ink);
    color: var(--fxl-sampler-wall);
  }
  &:focus-visible { outline: 2px solid var(--fxl-sampler-brass); outline-offset: 2px; }
}
.fxl-sampler .fxl-sampler-on { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fxl-sampler .fxl-sampler-sw {
  flex: none;
  inline-size: 18px;
  block-size: 18px;
  border-radius: 5px;
  --g: color-mix(in oklch, oklch(0.86 0.05 180) 70%, white);
  --s: color-mix(in oklch, oklch(0.7 0.05 190) 80%, white);
  background: var(--g);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--fxl-sampler-ink) 18%, transparent);
  &[data-k="clear"] { background: linear-gradient(135deg, var(--g) 40%, white 50%, var(--g) 60%); }
  &[data-k="reeded"] { background: repeating-linear-gradient(90deg, var(--s) 0 1px, var(--g) 1px 3px, white 3px 4px); }
  &[data-k="fluted"] { background: repeating-linear-gradient(90deg, var(--s) 0 2px, var(--g) 2px 6px, white 6px 7px); }
  &[data-k="hammered"] { background: radial-gradient(circle at 30% 30%, white 0 1.5px, transparent 2.5px) 0 0 / 6px 6px, radial-gradient(circle at 70% 70%, var(--s) 0 1.2px, transparent 2.2px) 0 0 / 6px 6px, var(--g); }
  &[data-k="rain"] { background: repeating-linear-gradient(90deg, var(--g) 0 2px, var(--s) 2px 2.6px, var(--g) 2.6px 4px, white 4px 4.5px, var(--g) 4.5px 7px); }
  &[data-k="satin"] { background: radial-gradient(circle at 35% 35%, white, var(--g) 70%); filter: blur(.2px); }
}

@container (max-width: 300px) {
  .fxl-sampler .fxl-sampler-sw { display: none; }
  .fxl-sampler .fxl-sampler-opt { justify-content: center; padding: 0 3px; font-size: 10.5px; }
}

.fxl-sampler .fxl-sampler-foot {
  grid-area: foot;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-block-start: 9px;
  border-block-start: 1px solid var(--fxl-sampler-rule);
}
.fxl-sampler .fxl-sampler-spec { display: grid; gap: 4px; min-inline-size: 0; }
.fxl-sampler .fxl-sampler-fin {
  font-size: 11.5px;
  line-height: 1.25;
  color: var(--fxl-sampler-muted);
  text-wrap: pretty;
}
.fxl-sampler .fxl-sampler-priv {
  display: flex;
  gap: 3px;
  & i {
    inline-size: 14px;
    block-size: 4px;
    border-radius: 2px;
    background: var(--fxl-sampler-rule);
    transition: background .3s;
    transition-delay: calc(var(--n, 0) * 50ms);
  }
  & i[data-on] { background: var(--fxl-sampler-clay); }
}
.fxl-sampler .fxl-sampler-price {
  display: grid;
  justify-items: end;
  gap: 2px;
  font-variant-numeric: tabular-nums;
  & span { font: 500 10px/1 ui-monospace, Menlo, monospace; color: var(--fxl-sampler-muted); }
  & b { font-size: clamp(17px, 6cqi, 21px); font-weight: 700; letter-spacing: -.03em; line-height: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .fxl-sampler .fxl-sampler-sheen { animation: none; --fxl-sampler-sheen: 22%; }
  .fxl-sampler .fxl-sampler-opt { transition: border-color .2s, background .2s; }
  .fxl-sampler .fxl-sampler-opt:active { scale: 1; }
  .fxl-sampler .fxl-sampler-grip { transition: none; }
  .fxl-sampler .fxl-sampler-priv i { transition: none; }
}

