const scene = root.querySelector('.fxl-sampler-scene');
const base = root.querySelector('.fxl-sampler-art');
const paneA = root.querySelector('.fxl-sampler-pane--a');
const paneB = root.querySelector('.fxl-sampler-pane--b');
const handle = root.querySelector('.fxl-sampler-handle');
const opts = [...root.querySelectorAll('.fxl-sampler-opt')];
const finEl = root.querySelector('.fxl-sampler-fin');
const privEl = root.querySelector('.fxl-sampler-priv');
const totalEl = root.querySelector('.fxl-sampler-total');
const lights = root.querySelectorAll('.fxl-sampler-light');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const AREA = 1.8;

/* Each glass is a filter on a clone of the bathroom: reeds and flutes are one
   cylindrical-lens tile repeated by feTile into a displacement map; hammered and rain
   glass are stretched feTurbulence that also drives feSpecularLighting, so the glints
   follow a point light that tracks the pointer. Filter ids are made unique here. */
const uid = Math.random().toString(36).slice(2, 8);
const ids = {};
root.querySelectorAll('.fxl-sampler-f').forEach((f) => { f.id = 'fxl-sampler-' + f.dataset.k + '-' + uid; ids[f.dataset.k] = f.id; });
function reedTile(pitch) {
  const c = document.createElement('canvas'); c.width = pitch; c.height = 2;
  const g = c.getContext('2d'), img = g.createImageData(pitch, 2), d = img.data;
  for (let x = 0; x < pitch; x++) {
    const u = (x + 0.5) / pitch, k = 1 - 2 * u;          /* a convex reed: the slice inside is mirrored */
    const shade = Math.cos((u - 0.3) * Math.PI * 1.4);
    for (let y = 0; y < 2; y++) {
      const o = (y * pitch + x) * 4;
      d[o] = Math.round(127.5 + 127 * k); d[o + 1] = 128; d[o + 2] = Math.round(127.5 + 110 * shade); d[o + 3] = 255;
    }
  }
  g.putImageData(img, 0, 0);
  return c.toDataURL();
}
root.querySelectorAll('.fxl-sampler-tile').forEach((t) => t.setAttribute('href', reedTile(+t.dataset.pitch)));

const cloneA = base.cloneNode(true), cloneB = base.cloneNode(true);
paneA.prepend(cloneA); paneB.prepend(cloneB);
let current = opts.findIndex((o) => o.getAttribute('aria-checked') === 'true');
const filterOf = (k) => (k === 'clear' ? 'none' : 'url(#' + ids[k] + ')');
paneA.style.filter = filterOf(opts[current].dataset.k);

let door = 40;
function setDoor(v, announce) {
  door = Math.max(0, Math.min(100, v));
  scene.style.setProperty('--fxl-sampler-door', door.toFixed(2));
  const cover = Math.round(100 - door);
  handle.setAttribute('aria-valuenow', Math.round(door));
  handle.setAttribute('aria-valuetext', 'Glass covers ' + cover + '% of the opening');
}

function money(v) { return '£' + v.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function select(i, focus) {
  if (i === current) { if (focus) opts[i].focus(); return; }
  const prev = current;
  current = i;
  opts.forEach((o, k) => { o.setAttribute('aria-checked', k === i ? 'true' : 'false'); o.tabIndex = k === i ? 0 : -1; });
  if (focus) opts[i].focus();
  const o = opts[i], k = o.dataset.k;
  finEl.textContent = o.dataset.fin;
  const p = +o.dataset.priv;
  privEl.setAttribute('aria-label', 'Privacy ' + p + ' of 5');
  [...privEl.children].forEach((d, n) => { d.style.setProperty('--n', n); d.toggleAttribute('data-on', n < p); });
  totalEl.textContent = money(AREA * +o.dataset.price);
  if (!reduce.matches) totalEl.animate([{ opacity: 0, transform: 'translateY(5px)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.2,.9,.2,1)' });
  /* the new glass slides in over the old from the leading edge of the panel */
  if (reduce.matches || prev < 0) { paneA.style.filter = filterOf(k); return; }
  paneB.style.filter = filterOf(k);
  paneB.style.visibility = 'visible';
  const d = door.toFixed(2) + '%';
  const anim = paneB.animate([
    { clipPath: 'inset(0 100% 0 ' + d + ')' },
    { clipPath: 'inset(0 0% 0 ' + d + ')' },
