  const n = opts.length;
  let i = null;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') i = (current + 1) % n;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') i = (current - 1 + n) % n;
