/* the glint light: follows the pointer, drifts on its own otherwise */
let lx = 0, ly = 0, cx = 0, cy = 0, pointerAt = -1e9, raf = 0, last = 0, visible = true;
function step(now) {
  if (!root.isConnected) return;
