.fxl-film {
  /* Re-theme with these four; the interference colours are physics, not palette. */
  --fxl-film-night: oklch(0.17 0.012 60);
  --fxl-film-brass: oklch(0.72 0.1 78);
  --fxl-film-ink: oklch(0.95 0.012 85);
  --fxl-film-accent: oklch(0.8 0.13 200);

  --fxl-film-muted: color-mix(in oklch, var(--fxl-film-ink) 58%, var(--fxl-film-night));
  --fxl-film-rule: color-mix(in oklch, var(--fxl-film-ink) 14%, transparent);
  --fxl-film-chipbg: color-mix(in oklch, var(--fxl-film-night) 70%, transparent);
  --fxl-film-out: cubic-bezier(.16, 1, .3, 1);
  --fxl-film-spring: linear(0, 0.1 5%, 0.45 14%, 0.88 25%, 1.06 33%, 1.08 39%, 1.04 47%, 0.99 62%, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 1.02;
  min-block-size: 220px;
  max-block-size: 400px;
  display: grid;
  grid-template-areas: "head dip" ". ." "read read";
  grid-template-columns: 1fr auto;
  grid-template-rows: auto 1fr auto;
  padding: clamp(12px, 4.4cqi, 18px);
  border-radius: 18px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxl-film-ink);
  background:
    radial-gradient(70% 60% at 50% 46%, color-mix(in oklch, var(--fxl-film-brass) 9%, var(--fxl-film-night)), var(--fxl-film-night) 70%);
  font: 400 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3) { margin: 0; }
}
.fxl-film .fxl-film-cv,
.fxl-film .fxl-film-surface { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
.fxl-film .fxl-film-cv { display: block; }
.fxl-film .fxl-film-probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }
.fxl-film .fxl-film-surface {
  z-index: 1;
  outline: none;
  cursor: crosshair;
  touch-action: pan-y;
  border-radius: inherit;
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--fxl-film-accent), inset 0 0 0 6px color-mix(in oklch, var(--fxl-film-accent) 20%, transparent); }
}
.fxl-film .fxl-film-head,
.fxl-film .fxl-film-read { position: relative; z-index: 2; pointer-events: none; }
.fxl-film .fxl-film-head { grid-area: head; display: grid; gap: 3px; align-self: start; }
.fxl-film .fxl-film-eyebrow {
  font: 600 9.5px/1.2 ui-monospace, Menlo, monospace;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--fxl-film-brass);
}
.fxl-film .fxl-film-title {
  font-size: clamp(14px, 5cqi, 18px);
  font-weight: 600;
  letter-spacing: -.015em;
  text-wrap: balance;
}
.fxl-film .fxl-film-dip {
  grid-area: dip;
  position: relative;
  z-index: 2;
  align-self: start;
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  block-size: 32px;
  padding: 0 13px 0 9px;
  border: 1px solid var(--fxl-film-rule);
  border-radius: 999px;
  background: var(--fxl-film-chipbg);
  color: var(--fxl-film-ink);
  backdrop-filter: blur(8px);
  font: 600 12px/1 system-ui, sans-serif;
  cursor: pointer;
  transition: border-color .2s, scale .45s var(--fxl-film-spring);
  & svg { inline-size: 17px; block-size: 17px; fill: none; stroke: var(--fxl-film-brass); stroke-width: 1.6; stroke-linecap: round; }
  &:hover { border-color: color-mix(in oklch, var(--fxl-film-brass) 60%, transparent); }
  &:active { scale: .94; }
  &:focus-visible { outline: 2px solid var(--fxl-film-accent); outline-offset: 2px; }
}
.fxl-film .fxl-film-read {
  grid-area: read;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}
.fxl-film .fxl-film-nm {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-variant-numeric: tabular-nums;
  & b { font-size: clamp(28px, 11cqi, 40px); font-weight: 250; letter-spacing: -.05em; line-height: .9; min-inline-size: 3ch; }
  & span { font: 600 11px/1 ui-monospace, Menlo, monospace; color: var(--fxl-film-muted); }
}
.fxl-film .fxl-film-meta { display: grid; justify-items: end; gap: 4px; text-align: end; }
.fxl-film .fxl-film-order {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 600;
}
.fxl-film .fxl-film-chip {
  inline-size: 10px;
  block-size: 10px;
  border-radius: 50%;
  background: var(--fxl-film-c, #888);
  box-shadow: 0 0 0 1px var(--fxl-film-rule), 0 0 10px var(--fxl-film-c, transparent);
}
.fxl-film .fxl-film-age {
  font: 500 10px/1.2 ui-monospace, Menlo, monospace;
  color: var(--fxl-film-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
@container (max-width: 290px) {
  .fxl-film .fxl-film-dip span { display: none; }
  .fxl-film .fxl-film-dip { padding: 0 8px; }
}

@media (prefers-reduced-motion: reduce) {
  .fxl-film .fxl-film-dip { transition: border-color .2s; }
  .fxl-film .fxl-film-dip:active { scale: 1; }
}

