const cv = root.querySelector('.fxl-film-cv');
const surface = root.querySelector('.fxl-film-surface');
const probe = root.querySelector('.fxl-film-probe');
const dipBtn = root.querySelector('.fxl-film-dip');
const read = root.querySelector('.fxl-film-read');
const headEl = root.querySelector('.fxl-film-head');
const numEl = root.querySelector('.fxl-film-num');
const nameEl = root.querySelector('.fxl-film-name');
const agevEl = root.querySelector('.fxl-film-agev');
const minEl = root.querySelector('.fxl-film-min');
const ctx = cv.getContext('2d');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* Colour is physics: reflectance of a water film (n = 1.33) is 4R0 sin^2(2 pi n d / lambda),
   integrated against an analytic fit of the CIE 1931 observer and converted to sRGB into a
   1024-entry thickness LUT. The film itself is a thickness field that thins from the top,
   slides down by gravity, swirls on a curl-noise flow, and takes the pointer's breath. */
const NF = 1.33, R0 = Math.pow((NF - 1) / (NF + 1), 2), TMAX = 1400, LN = 1024;
const LUT = new Uint8ClampedArray(LN * 3);
(function buildLut() {
  const g = (l, m, a, b) => { const s = l < m ? a : b; return Math.exp(-0.5 * (l - m) * (l - m) / (s * s)); };
  const xb = (l) => 1.056 * g(l, 599.8, 37.9, 31) + 0.362 * g(l, 442, 16, 26.7) - 0.065 * g(l, 501.1, 20.4, 26.2);
  const yb = (l) => 0.821 * g(l, 568.8, 46.9, 40.5) + 0.286 * g(l, 530.9, 16.3, 31.1);
  const zb = (l) => 1.217 * g(l, 437, 11.8, 36) + 0.681 * g(l, 459, 26, 13.8);
  let ySum = 0;
  for (let l = 380; l <= 780; l += 5) ySum += yb(l);
  const enc = (c) => { c = Math.max(0, c); return 255 * (c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055); };
  const expo = 0.82 / (4 * R0);
  for (let i = 0; i < LN; i++) {
    const d = i / (LN - 1) * TMAX;
    let X = 0, Y = 0, Z = 0;
    for (let l = 380; l <= 780; l += 5) {
      const s = Math.sin(2 * Math.PI * NF * d / l), R = 4 * R0 * s * s;
      X += R * xb(l); Y += R * yb(l); Z += R * zb(l);
    }
    X = X / ySum * expo; Y = Y / ySum * expo; Z = Z / ySum * expo;
    const r = 3.2406 * X - 1.5372 * Y - 0.4986 * Z, gg = -0.9689 * X + 1.8758 * Y + 0.0415 * Z, b = 0.0557 * X - 0.204 * Y + 1.057 * Z;
    LUT[i * 3] = enc(r); LUT[i * 3 + 1] = enc(gg); LUT[i * 3 + 2] = enc(b);
  }
})();
function lut(t) { const i = Math.max(0, Math.min(LN - 1, Math.round(t / TMAX * (LN - 1)))) * 3; return [LUT[i], LUT[i + 1], LUT[i + 2]]; }
function colourName(t) {
  if (t < 28) return 'black film';
  if (t < 90) return 'silver grey';
  const [r, g, b] = lut(t), mx = Math.max(r, g, b), mn = Math.min(r, g, b);
  if (mx - mn < 28) return mx > 150 ? 'pearl white' : 'pewter';
  let h = 0;
  if (mx === r) h = ((g - b) / (mx - mn) + 6) % 6; else if (mx === g) h = (b - r) / (mx - mn) + 2; else h = (r - g) / (mx - mn) + 4;
  h *= 60;
  const names = [[15, 'red'], [40, 'orange'], [62, 'gold'], [80, 'straw yellow'], [150, 'green'], [190, 'teal'], [235, 'blue'], [270, 'indigo'], [320, 'magenta'], [361, 'rose']];
  for (const [lim, n] of names) if (h < lim) return n;
  return 'red';
}
function orderOf(t) { const o = 1 + Math.floor(2 * NF * t / 560); return ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh'][Math.min(6, o - 1)] + ' order'; }

const N = 112, C0 = (N - 1) / 2, RC = N / 2 - 1.5;
let T = new Float32Array(N * N), T2 = new Float32Array(N * N), U = new Float32Array(N * N), V = new Float32Array(N * N);
const IN = new Uint8Array(N * N);
for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) IN[j * N + i] = Math.hypot(i - C0, j - C0) <= RC + 1 ? 1 : 0;
const small = document.createElement('canvas'); small.width = small.height = N;
const sctx = small.getContext('2d');
const img = sctx.createImageData(N, N);

let W = 0, H = 0, dpr = 1, cx = 0, cy = 0, R = 0;
let state = 'film', age = 0, stateT = 0, popX = 0, popY = 0, popR = 0, spray = [];
let raf = 0, last = 0, visible = true, probeX = null, probeY = null, uiAt = 0, minT = 0;
let ptr = null, downAt = 0, downPt = null;

function fresh() {
  const s = Math.random() * 10;
  for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
    const k = j * N + i, y = j / (N - 1);
    T[k] = 150 + 1020 * Math.pow(y, 1.55) + 70 * Math.sin(i * 0.11 + s) * Math.sin(j * 0.07 + s * 0.6);
    U[k] = 0; V[k] = 0;
  }
  age = 0;
}

function layout() {
  W = cv.clientWidth; H = cv.clientHeight;
  if (!W || !H) return;
  dpr = Math.min(2, devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  /* the loop sits in whatever room the header and the readout leave */
  const top = headEl.offsetTop + headEl.offsetHeight + 12, bottom = read.offsetTop - 12;
  R = Math.max(36, Math.min(W * 0.36, (bottom - top) / 2));
  cx = W / 2; cy = (top + bottom) / 2;
}

function sample(A, x, y) {
  /* clamp to the loop: the film is bounded by the wire */
  const dx = x - C0, dy = y - C0, d = Math.hypot(dx, dy);
  if (d > RC) { x = C0 + dx / d * RC; y = C0 + dy / d * RC; }
  const i = Math.floor(x), j = Math.floor(y), fx = x - i, fy = y - j, k = j * N + i;
  return (A[k] * (1 - fx) + A[k + 1] * fx) * (1 - fy) + (A[k + N] * (1 - fx) + A[k + N + 1] * fx) * fy;
}

function sim(dt, now) {
  const calm = reduce.matches, t = now / 1000;
  const sw = calm ? 0 : 1.9;
  const decay = Math.exp(-1.7 * dt);
  let mn = 1e9;
  for (let j = 1; j < N - 1; j++) {
    const y01 = j / (N - 1), thin = (calm ? 0.25 : 1) * (0.055 * (1 - y01) * (1 - y01) + 0.0035);
    for (let i = 1; i < N - 1; i++) {
      const k = j * N + i;
      if (!IN[k]) { T2[k] = T[k]; continue; }
      /* curl of a stream function made of three drifting waves: divergence-free swirl */
      const x = i * 0.085, y = j * 0.085;
      const u = sw * (Math.cos(y * 1.3 + t * 0.21) * 1.3 + Math.cos(x * 0.7 + y * 1.9 - t * 0.17) * 1.9 * 0.8);
      const v = -sw * (Math.cos(x * 1.1 - t * 0.19) * 1.1 + Math.cos(x * 0.7 + y * 1.9 - t * 0.17) * 0.7 * 0.8);
      const th = T[k] / 1000;
      const vx = u + U[k], vy = v + V[k] + (calm ? 0.3 : 1.4) * th * th;
      let nt = sample(T, i - vx * dt, j - vy * dt);
      nt = nt * 0.94 + 0.015 * (T[k - 1] + T[k + 1] + T[k - N] + T[k + N]);
      nt *= 1 - thin * dt;
      T2[k] = nt;
      if (nt < mn) mn = nt;
      U[k] *= decay; V[k] *= decay;
    }
  }
  const tmp = T; T = T2; T2 = tmp;
  minT = mn;
}

function blow(px, py, vx, vy, strength) {
  /* px,py in cells; vx,vy in cells/s */
  const r = 9;
  for (let j = Math.max(1, Math.floor(py - r)); j < Math.min(N - 1, py + r); j++) {
    for (let i = Math.max(1, Math.floor(px - r)); i < Math.min(N - 1, px + r); i++) {
      const d2 = (i - px) * (i - px) + (j - py) * (j - py);
      const w = Math.exp(-d2 / (r * r * 0.35)) * strength;
      const k = j * N + i;
      U[k] += vx * w; V[k] += vy * w;
    }
  }
}

function toCell(x, y) { return [(x - (cx - R)) / (2 * R) * (N - 1), (y - (cy - R)) / (2 * R) * (N - 1)]; }

function pop(x, y) {
  if (state !== 'film') return;
  state = 'popping'; stateT = 0; popX = x; popY = y; popR = 0;
  if (!reduce.matches) {
    for (let n = 0; n < 34; n++) {
      const a = Math.random() * 6.2832, sp = 60 + Math.random() * 160;
      spray.push({ x: cx - R + x / (N - 1) * 2 * R, y: cy - R + y / (N - 1) * 2 * R, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, life: 0.5 + Math.random() * 0.4 });
    }
  }
}
function dip() {
  if (state === 'dipping') return;
  state = 'dipping'; stateT = 0; spray = []; fresh();
  kick();
}

function render(dt) {
  const d = img.data;
  const popping = state === 'popping', dipping = state === 'dipping', empty = state === 'empty';
  const front = dipping ? Math.min(1, stateT / 0.75) : 1;
  for (let j = 0; j < N; j++) {
    for (let i = 0; i < N; i++) {
      const k = j * N + i, o = k * 4;
      if (empty) { d[o + 3] = 0; continue; }
      /* cells outside the wire borrow the nearest film so the upscaled edge stays clean */
      let a = 255, t = IN[k] ? T[k] : sample(T, Math.max(1, Math.min(N - 2, i)), Math.max(1, Math.min(N - 2, j)));
      if (popping) {
        const dd = Math.hypot(i - popX, j - popY);
        if (dd < popR) { d[o + 3] = 0; continue; }
        if (dd < popR + 3) t = 1300;                         /* the retracting rim gathers liquid */
      }
      if (dipping) {
        const h = (N - 1 - j) / (N - 1), e = front * 1.08 - h;
        if (e < 0) { d[o + 3] = 0; continue; }
        if (e < 0.04) t = 1200;                              /* meniscus on the rising edge */
        a = Math.min(255, e * 255 * 12);
      }
      const q = Math.max(0, Math.min(LN - 1, Math.round(t / TMAX * (LN - 1)))) * 3;
      d[o] = LUT[q]; d[o + 1] = LUT[q + 1]; d[o + 2] = LUT[q + 2]; d[o + 3] = a;
    }
  }
  sctx.putImageData(img, 0, 0);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  /* stick and loop: drawn first so the film sits inside the wire */
  const brass = probeColour('--fxl-film-brass', '#c9a45a');
  ctx.lineCap = 'round';
  ctx.strokeStyle = brass; ctx.lineWidth = Math.max(3, R * 0.045);
  ctx.beginPath(); ctx.moveTo(cx + R * 0.97, cy + R * 0.2); ctx.lineTo(cx + R * 2.4, cy + R * 0.58); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.35)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(cx + R * 1.02, cy + R * 0.17); ctx.lineTo(cx + R * 2.4, cy + R * 0.54); ctx.stroke();
  ctx.save();
  ctx.beginPath(); ctx.arc(cx, cy, R, 0, 6.2832); ctx.clip();
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
  ctx.globalAlpha = 0.96;
  ctx.drawImage(small, cx - R, cy - R, 2 * R, 2 * R);
  ctx.globalAlpha = 1;
  if (state === 'film') {
    /* two window reflections and a cool rim: the film is a curved mirror too */
    const g1 = ctx.createLinearGradient(cx - R * 0.6, cy - R * 0.7, cx - R * 0.2, cy - R * 0.1);
    g1.addColorStop(0, 'rgba(255,255,255,0.16)'); g1.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g1;
    ctx.beginPath(); ctx.ellipse(cx - R * 0.42, cy - R * 0.42, R * 0.3, R * 0.16, -0.75, 0, 6.2832); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.07)';
    ctx.beginPath(); ctx.ellipse(cx + R * 0.48, cy + R * 0.38, R * 0.14, R * 0.07, -0.75, 0, 6.2832); ctx.fill();
  }
  /* Plateau border: the film thickens into a pale lip where it meets the wire */
  if (!empty) {
    ctx.strokeStyle = 'rgba(255,250,240,0.16)'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(cx, cy, R - 1, 0, 6.2832); ctx.stroke();
