.fxl-honey {
  /* Re-theme with these four; the honey's depth, rim and glints derive from them. */
  --fxl-honey-cream: oklch(0.965 0.02 88);
  --fxl-honey-honey: oklch(0.74 0.16 70);
  --fxl-honey-ink: oklch(0.28 0.04 60);
  --fxl-honey-lid: oklch(0.36 0.05 150);

  --fxl-honey-muted: color-mix(in oklch, var(--fxl-honey-ink) 58%, var(--fxl-honey-cream));
  --fxl-honey-rule: color-mix(in oklch, var(--fxl-honey-ink) 13%, transparent);
  --fxl-honey-deep: color-mix(in oklch, var(--fxl-honey-honey) 62%, oklch(0.36 0.1 45));
  --fxl-honey-out: cubic-bezier(.2, .9, .2, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 1.14;
  min-block-size: 280px;
  max-block-size: 420px;
  display: grid;
  grid-template-areas: "head visc" ". ." "temp temp";
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  column-gap: 10px;
  padding: clamp(12px, 4.4cqi, 18px);
  border-radius: 18px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxl-honey-ink);
  background:
    radial-gradient(60% 46% at 50% 52%, color-mix(in oklch, var(--fxl-honey-honey) 16%, var(--fxl-honey-cream)), transparent 70%),
    var(--fxl-honey-cream);
  box-shadow: inset 0 0 0 1px var(--fxl-honey-rule);
  font: 400 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3) { margin: 0; }
}
.fxl-honey .fxl-honey-cv,
.fxl-honey .fxl-honey-jar { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
.fxl-honey .fxl-honey-cv { display: block; }
.fxl-honey .fxl-honey-probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }
