  cursor: grab;
  touch-action: pan-y;
  border-radius: inherit;
  &:active { cursor: grabbing; }
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--fxl-honey-lid), inset 0 0 0 6px color-mix(in oklch, var(--fxl-honey-lid) 18%, transparent); }
}
.fxl-honey .fxl-honey-head,
.fxl-honey .fxl-honey-visc,
.fxl-honey .fxl-honey-temp { position: relative; z-index: 2; }
.fxl-honey .fxl-honey-head,
.fxl-honey .fxl-honey-visc { pointer-events: none; }
