.fxl-honey .fxl-honey-eyebrow {
  font: 600 9.5px/1.25 ui-monospace, Menlo, monospace;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--fxl-honey-muted);
  text-wrap: balance;
}
.fxl-honey .fxl-honey-title {
  font-size: clamp(15px, 5.4cqi, 19px);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.1;
  text-wrap: balance;
}
.fxl-honey .fxl-honey-visc {
  grid-area: visc;
  align-self: start;
  display: grid;
  grid-template-columns: auto auto;
  justify-content: end;
  align-items: baseline;
  column-gap: 3px;
  text-align: end;
  font-variant-numeric: tabular-nums;
}
.fxl-honey .fxl-honey-eta {
  font-size: clamp(20px, 7.6cqi, 28px);
  font-weight: 700;
  letter-spacing: -.04em;
  line-height: 1;
  color: var(--fxl-honey-deep);
}
.fxl-honey .fxl-honey-unit { font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--fxl-honey-muted); }
.fxl-honey .fxl-honey-cap {
  grid-column: 1 / -1;
  font: 500 9.5px/1.3 ui-monospace, Menlo, monospace;
  color: var(--fxl-honey-muted);
  white-space: nowrap;
}
.fxl-honey .fxl-honey-temp {
  grid-area: temp;
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas: "label range" ". ticks";
  align-items: center;
  column-gap: 10px;
  row-gap: 2px;
  padding: 8px 12px 7px 10px;
  border-radius: 14px;
  background: color-mix(in oklch, var(--fxl-honey-cream) 82%, transparent);
  backdrop-filter: blur(8px);
  box-shadow: inset 0 0 0 1px var(--fxl-honey-rule), 0 8px 18px -14px color-mix(in oklch, var(--fxl-honey-ink) 60%, transparent);
}
.fxl-honey .fxl-honey-tl {
