  display: inline-flex;
  align-items: center;
  gap: 3px;
  min-inline-size: 64px;
  font-variant-numeric: tabular-nums;
  & svg { inline-size: 18px; block-size: 18px; fill: none; stroke: var(--fxl-honey-deep); stroke-width: 1.6; stroke-linecap: round; }
}
.fxl-honey .fxl-honey-out { font-size: 15px; font-weight: 700; letter-spacing: -.02em; }
.fxl-honey .fxl-honey-range {
  grid-area: range;
  inline-size: 100%;
  margin: 0;
  accent-color: var(--fxl-honey-deep);
