  &:focus-visible { outline: 2px solid var(--fxl-honey-lid); outline-offset: 4px; border-radius: 4px; }
}
.fxl-honey .fxl-honey-ticks {
  grid-area: ticks;
  display: flex;
  justify-content: space-between;
  font: 500 9px/1 ui-monospace, Menlo, monospace;
  color: var(--fxl-honey-muted);
  & span:nth-child(2), & span:nth-child(3) { opacity: .75; }
}
@container (max-width: 300px) {
  .fxl-honey .fxl-honey-batch { display: none; }
  .fxl-honey .fxl-honey-ticks span:nth-child(2), .fxl-honey .fxl-honey-ticks span:nth-child(3) { display: none; }
  .fxl-honey .fxl-honey-cap { white-space: normal; }
}

@media (prefers-reduced-motion: reduce) {
  .fxl-honey .fxl-honey-jar { cursor: grab; }
}

