const cv = root.querySelector('.fxl-honey-cv');
const jarEl = root.querySelector('.fxl-honey-jar');
const probe = root.querySelector('.fxl-honey-probe');
const range = root.querySelector('.fxl-honey-range');
const outEl = root.querySelector('.fxl-honey-out');
const etaEl = root.querySelector('.fxl-honey-eta');
const tcEl = root.querySelector('.fxl-honey-tc');
const headEl = root.querySelector('.fxl-honey-head');
const viscEl = root.querySelector('.fxl-honey-visc');
const tempEl = root.querySelector('.fxl-honey-temp');
const ctx = cv.getContext('2d');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* Clavet, Beaudoin and Poulin's viscoelastic SPH (2005): gravity, pairwise viscosity
   impulses, then double density relaxation that pushes neighbours apart with a far and
   a near pressure. It runs in the jar's own frame, so tilting the jar only rotates
   gravity. Temperature sets the viscosity through an Arrhenius-style fit for honey. */
const A = 46, B = 66, RC = 16, HH = 10, NP = 470, RHO0 = 2, KS = 0.12, KN = 0.35;
const x = new Float32Array(NP), y = new Float32Array(NP), vx = new Float32Array(NP), vy = new Float32Array(NP);
const px = new Float32Array(NP), py = new Float32Array(NP);
const CELL = HH, GW = Math.ceil(2 * (A + 4) / CELL) + 1, GH = Math.ceil(2 * (B + 4) / CELL) + 1;
const head = new Int32Array(GW * GH), nxt = new Int32Array(NP);
const nbI = new Int32Array(NP * 40), nbF = new Float32Array(NP * 40 * 3);
let SIG = 0.5, BETA = 0.06, MU = 0.4, DAMP = 0.996;

(function seedFluid() {
  let i = 0;
  for (let yy = B - 3; i < NP; yy -= 4.6) for (let xx = -A + 3; xx <= A - 3 && i < NP; xx += 4.6) {
    x[i] = xx + (Math.random() - 0.5) * 0.4; y[i] = yy; i++;
  }
})();
function cellOf(p) {
  const gx = Math.min(GW - 1, Math.max(0, ((x[p] + A + 4) / CELL) | 0));
  const gy = Math.min(GH - 1, Math.max(0, ((y[p] + B + 4) / CELL) | 0));
