}
function grid() { head.fill(-1); for (let p = 0; p < NP; p++) { const c = cellOf(p); nxt[p] = head[c]; head[c] = p; } }
function sdf(X, Y) {
  const qx = Math.abs(X) - (A - RC), qy = Math.abs(Y) - (B - RC);
  return Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - RC;
}
function simStep(gx, gy) {
  for (let p = 0; p < NP; p++) { vx[p] = vx[p] * DAMP + gx; vy[p] = vy[p] * DAMP + gy; }
  grid();
  const h2 = HH * HH;
  for (let p = 0; p < NP; p++) {
    const c = cellOf(p), cx = c % GW, cy = (c / GW) | 0;
    for (let oy = -1; oy <= 1; oy++) for (let ox = -1; ox <= 1; ox++) {
      const gx2 = cx + ox, gy2 = cy + oy;
      if (gx2 < 0 || gy2 < 0 || gx2 >= GW || gy2 >= GH) continue;
      for (let q = head[gy2 * GW + gx2]; q !== -1; q = nxt[q]) {
        if (q <= p) continue;
        const dx = x[q] - x[p], dy = y[q] - y[p], r2 = dx * dx + dy * dy;
        if (r2 >= h2 || r2 < 1e-9) continue;
        const r = Math.sqrt(r2), nx = dx / r, ny = dy / r;
        const u = (vx[p] - vx[q]) * nx + (vy[p] - vy[q]) * ny;
