/* ---------- rendering ---------- */
const FX = 2 * A + 8, FY = 2 * B + 8, FR = 8, FR2 = FR * FR, TH = 0.42;
const field = new Float32Array(FX * FY);
const fcv = document.createElement('canvas'); fcv.width = FX; fcv.height = FY;
