let W = 0, H = 0, dpr = 1, S = 1, jx = 0, jy = 0, pal = null;

function rgbOf(name, fb) {
  probe.style.color = 'var(' + name + ')';
  const c = document.createElement('canvas'); c.width = c.height = 1;
  const g = c.getContext('2d'); g.fillStyle = fb; g.fillStyle = getComputedStyle(probe).color; g.fillRect(0, 0, 1, 1);
