function palette() {
  const honey = rgbOf('--fxl-honey-honey', '#e3a23a'), ink = rgbOf('--fxl-honey-ink', '#3d2b1c');
  const lid = rgbOf('--fxl-honey-lid', '#2e4a3a'), cream = rgbOf('--fxl-honey-cream', '#f7f0e2');
  const mix = (a, b, t) => a.map((v, i) => v + (b[i] - v) * t);
  pal = { honey, ink, lid, cream, light: mix(honey, [255, 226, 130], 0.42), deep: mix(honey, [120, 48, 6], 0.5), mix };
}
const css = (c, a) => 'rgba(' + c.map((v) => Math.round(v)).join(',') + ',' + (a === undefined ? 1 : a) + ')';

function layout() {
  W = cv.clientWidth; H = cv.clientHeight;
  if (!W || !H) return;
  dpr = Math.min(2, devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  /* the jar stands in the room between the header and the temperature panel */
  const top = Math.max(headEl.offsetTop + headEl.offsetHeight, viscEl.offsetTop + viscEl.offsetHeight) + 8;
  const bottom = tempEl.offsetTop - 10;
  S = Math.max(0.4, Math.min((bottom - top) / (2 * B + 20), W * 0.42 / (2 * A + 8)));
  jx = W / 2; jy = top + (B + 16) * S;
  palette();
}

function splat() {
  field.fill(0);
  for (let p = 0; p < NP; p++) {
    const fx = x[p] + A + 4, fy = y[p] + B + 4;
    const i0 = Math.max(0, Math.floor(fx - FR)), i1 = Math.min(FX - 1, Math.ceil(fx + FR));
    const j0 = Math.max(0, Math.floor(fy - FR)), j1 = Math.min(FY - 1, Math.ceil(fy + FR));
    for (let j = j0; j <= j1; j++) {
      const dy = j + 0.5 - fy, dy2 = dy * dy, row = j * FX;
      for (let i = i0; i <= i1; i++) {
        const dx = i + 0.5 - fx, d2 = dx * dx + dy2;
        if (d2 < FR2) { const w = 1 - d2 / FR2; field[row + i] += w * w * w; }
      }
