  }
  /* one separable box pass: the surface reads as liquid, not as 470 particles */
  for (let j = 0; j < FY; j++) {
    const r = j * FX;
    let prev = field[r];
    for (let i = 1; i < FX - 1; i++) { const c = field[r + i]; field[r + i] = (prev + c + field[r + i + 1]) / 3; prev = c; }
  }
  for (let i = 0; i < FX; i++) {
    let prev = field[i];
    for (let j = 1; j < FY - 1; j++) { const k = j * FX + i, c = field[k]; field[k] = (prev + c + field[k + FX]) / 3; prev = c; }
  }
  const d = fimg.data, P = pal;
  for (let j = 1; j < FY - 1; j++) {
    for (let i = 1; i < FX - 1; i++) {
      const k = j * FX + i, f = field[k], o = k * 4;
      if (f < TH - 0.08) { d[o + 3] = 0; continue; }
      let a = (f - (TH - 0.08)) / 0.16; if (a > 1) a = 1;
      let t = (f - TH) / 1.6; if (t < 0) t = 0; else if (t > 1) t = 1;
      const gx = field[k + 1] - field[k - 1], gy = field[k + FX] - field[k - FX], gl = Math.hypot(gx, gy) + 1e-4;
      /* a round jar: light runs through the middle, the walls bend it away, so the
         core glows gold and the sides and the fresh surface edge go deep amber */
      const ux = (i - A - 4) / A, uy = (j - B - 4) / B;
      const core = Math.exp(-ux * ux * 2.6);
      let m = 0.18 + 0.62 * ux * ux + 0.22 * (1 - t) - 0.32 * core + 0.12 * (uy > 0 ? uy : 0);
      if (m < 0) m = 0; else if (m > 1) m = 1;
      let s = (-gx * 0.5 - gy * 0.87) / gl; s = s > 0 ? Math.pow(s, 14) * (1 - t) * 190 : 0;
      d[o] = P.light[0] + (P.deep[0] - P.light[0]) * m + s;
      d[o + 1] = P.light[1] + (P.deep[1] - P.light[1]) * m + s;
      d[o + 2] = P.light[2] + (P.deep[2] - P.light[2]) * m + s * 0.9;
      d[o + 3] = a * 255;
    }
  }
  fctx.putImageData(fimg, 0, 0);
}

function roundBox(g, hw, hh, r) {
  g.beginPath();
  g.moveTo(-hw + r, -hh); g.lineTo(hw - r, -hh); g.quadraticCurveTo(hw, -hh, hw, -hh + r);
  g.lineTo(hw, hh - r); g.quadraticCurveTo(hw, hh, hw - r, hh); g.lineTo(-hw + r, hh);
  g.quadraticCurveTo(-hw, hh, -hw, hh - r); g.lineTo(-hw, -hh + r); g.quadraticCurveTo(-hw, -hh, -hw + r, -hh);
  g.closePath();
}

function draw(theta) {
  if (!W) return;
  const P = pal;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  /* the table the jar stands on */
  const tableY = jy + (B + 4) * S;
  const tg = ctx.createLinearGradient(0, tableY, 0, H);
  tg.addColorStop(0, css(P.ink, 0.07)); tg.addColorStop(1, css(P.ink, 0.02));
  ctx.fillStyle = tg; ctx.fillRect(0, tableY, W, H - tableY);
  /* contact shadow on the table, widening as the jar tips */
  const sw = (A + 6) * S * (1 + Math.abs(Math.sin(theta)) * 0.5);
  const sh = ctx.createRadialGradient(jx, jy + (B + 6) * S, 0, jx, jy + (B + 6) * S, sw * 1.3);
  sh.addColorStop(0, css(P.ink, 0.22)); sh.addColorStop(1, css(P.ink, 0));
  ctx.fillStyle = sh;
  ctx.beginPath(); ctx.ellipse(jx, jy + (B + 6) * S, sw * 1.3, sw * 0.22, 0, 0, 6.2832); ctx.fill();
  ctx.save();
  ctx.translate(jx, jy); ctx.rotate(theta); ctx.scale(S, S);
  /* back wall of the glass */
  roundBox(ctx, A + 3, B + 3, RC + 3);
  ctx.fillStyle = css(P.cream, 0.55); ctx.fill();
  /* honey */
  ctx.save();
  roundBox(ctx, A, B, RC); ctx.clip();
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(fcv, -A - 4, -B - 4, FX, FY);
  ctx.strokeStyle = 'rgba(255,250,235,0.7)'; ctx.lineWidth = 0.5;
  for (const b of BUBBLES) {
    const fi = Math.round(x[b] + A + 4), fj = Math.round(y[b] + B + 4);
    if (fi < 1 || fj < 1 || fi >= FX - 1 || fj >= FY - 1 || field[fj * FX + fi] < TH + 0.9) continue;
    ctx.beginPath(); ctx.arc(x[b], y[b], 1.2, 0, 6.2832); ctx.stroke();
  }
  ctx.restore();
  /* glass: wall, two window highlights, a heavy base */
  roundBox(ctx, A + 3, B + 3, RC + 3);
  ctx.lineWidth = 3; ctx.strokeStyle = css(P.mix(P.cream, [120, 150, 150], 0.35), 0.75); ctx.stroke();
  ctx.lineWidth = 0.8; ctx.strokeStyle = 'rgba(255,255,255,0.9)'; ctx.stroke();
  const hl = ctx.createLinearGradient(-A, 0, -A + 16, 0);
  hl.addColorStop(0, 'rgba(255,255,255,0)'); hl.addColorStop(0.35, 'rgba(255,255,255,0.55)'); hl.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = hl; ctx.fillRect(-A + 2, -B + 14, 14, 2 * B - 34);
  ctx.fillStyle = 'rgba(255,255,255,0.32)'; ctx.fillRect(A - 9, -B + 20, 3.5, 2 * B - 60);
  ctx.fillStyle = css(P.mix(P.cream, [90, 120, 120], 0.25), 0.45);
  ctx.beginPath(); ctx.ellipse(0, B + 1.2, A - 4, 2.4, 0, 0, 6.2832); ctx.fill();
  /* lid with knurled edge */
  ctx.fillStyle = css(P.lid);
  ctx.translate(0, -B - 9); roundBox(ctx, A - 1, 6, 3); ctx.fill();
  ctx.strokeStyle = css(P.mix(P.lid, [255, 255, 255], 0.25)); ctx.lineWidth = 0.7;
  for (let k = -A + 4; k <= A - 4; k += 3.2) { ctx.beginPath(); ctx.moveTo(k, -4.5); ctx.lineTo(k, 4.5); ctx.stroke(); }
  ctx.fillStyle = 'rgba(255,255,255,0.22)'; ctx.fillRect(-A + 2, -5, 2 * A - 4, 2.2);
  ctx.translate(0, B + 9);
  /* label band */
  const ly = B * 0.5, lh = B * 0.38;
  ctx.fillStyle = css(P.cream);
  ctx.fillRect(-A - 3, ly, 2 * A + 6, lh);
  ctx.fillStyle = css(P.lid); ctx.fillRect(-A - 3, ly, 2 * A + 6, 2.2); ctx.fillRect(-A - 3, ly + lh - 2.2, 2 * A + 6, 2.2);
  ctx.fillStyle = css(P.ink);
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '750 8.4px system-ui, sans-serif';
  ctx.fillText('LARKHILL', 0, ly + lh * 0.37);
  ctx.font = '500 5px ui-monospace, Menlo, monospace';
  ctx.fillText('HEATHER  ·  340 g', 0, ly + lh * 0.74);
  ctx.restore();
}

/* ---------- tilt, temperature, loop ---------- */
let theta = 0, omega = 0, target = 0, held = false, dragFrom = null, lastInput = -1e9;
let raf = 0, last = 0, visible = true, acc = 0, ke = 1;
function setTemp(t) {
  const eta = 10000 * Math.exp(-0.135 * (t - 20));
  const n = Math.max(0, Math.min(1, (Math.log10(eta) - 2.5) / 2.1));
  SIG = 0.04 + 0.85 * Math.pow(n, 1.4); BETA = 0.01 + 0.09 * n; MU = 0.12 + 0.5 * n; DAMP = 0.999 - 0.006 * n;
  outEl.textContent = t + ' °C';
  range.setAttribute('aria-valuetext', t + ' degrees Celsius');
  tcEl.textContent = t;
  etaEl.textContent = Number(eta.toPrecision(3)).toLocaleString('en-GB');
  kick();
}
function setAria() {
  const deg = Math.round(target * 180 / Math.PI);
  jarEl.setAttribute('aria-valuenow', deg);
  jarEl.setAttribute('aria-valuetext', deg === 0 ? 'Upright' : 'Tipped ' + Math.abs(deg) + ' degrees ' + (deg > 0 ? 'right' : 'left'));
}
function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible || !W) return;
  const dt = Math.min(0.05, (now - last) / 1000 || 0.016); last = now;
  const calm = reduce.matches;
  let tt = target;
  if (!held && !dragFrom && !calm && now - lastInput > 3500) tt = 0.13 * Math.sin(now / 1000 * 0.85);
  if (calm) { theta += (tt - theta) * (1 - Math.pow(0.0005, dt)); omega = 0; }
  else { omega += ((tt - theta) * 46 - omega * 6.5) * dt; theta += omega * dt; }
  acc += dt;
  let n = 0;
  while (acc > 1 / 60 && n < 3) {
    const g = 0.055;
    ke = simStep(Math.sin(theta) * g, Math.cos(theta) * g);
    ke = simStep(Math.sin(theta) * g, Math.cos(theta) * g);
    acc -= 1 / 60; n++;
  }
  if (acc > 0.1) acc = 0;
  splat();
  draw(theta);
  const settling = Math.abs(tt - theta) > 0.002 || ke > 0.0004;
  if (settling || !calm || dragFrom) raf = requestAnimationFrame(step);
}
function kick() { if (!raf && visible && root.isConnected && W) { last = performance.now(); raf = requestAnimationFrame(step); } }

jarEl.addEventListener('pointerdown', (e) => {
  dragFrom = { x: e.clientX, t: target };
  held = false; lastInput = performance.now();
  try { jarEl.setPointerCapture(e.pointerId); } catch (err) {}
  kick();
});
jarEl.addEventListener('pointermove', (e) => {
  if (!dragFrom) return;
  target = Math.max(-0.61, Math.min(0.61, dragFrom.t + (e.clientX - dragFrom.x) * 0.009));
  lastInput = performance.now(); setAria(); kick();
});
const release = () => { if (!dragFrom) return; dragFrom = null; target = 0; lastInput = performance.now(); setAria(); kick(); };
jarEl.addEventListener('pointerup', release);
jarEl.addEventListener('pointercancel', release);
jarEl.addEventListener('keydown', (e) => {
  const d = { ArrowLeft: -1, ArrowDown: -1, ArrowRight: 1, ArrowUp: 1 }[e.key];
  if (d) { e.preventDefault(); held = true; target = Math.max(-0.61, Math.min(0.61, target + d * 0.1745)); }
  else if (e.key === 'Home' || e.key === 'Escape') { e.preventDefault(); held = false; target = 0; }
  else return;
  lastInput = performance.now(); setAria(); kick();
});
jarEl.addEventListener('blur', () => { if (held) { held = false; target = 0; setAria(); kick(); } });
range.addEventListener('input', () => setTemp(+range.value));

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } layout(); splat(); draw(theta); kick(); });
ro.observe(cv);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) kick();
};
document.addEventListener('visibilitychange', onVis);
reduce.addEventListener('change', kick);
setTemp(+range.value);
for (let f = 0; f < 140; f++) simStep(0, 0.055);   /* settle before the first frame */
layout();
kick();

