.fxl-ferro {
  /* Re-theme with these four. The fluid is drawn from --fxl-ferro-fluid, the coil from copper. */
  --fxl-ferro-paper: oklch(0.945 0.008 85);
  --fxl-ferro-fluid: oklch(0.17 0.012 265);
  --fxl-ferro-copper: oklch(0.64 0.13 50);
  --fxl-ferro-ink: oklch(0.26 0.015 260);

  --fxl-ferro-muted: color-mix(in oklch, var(--fxl-ferro-ink) 55%, var(--fxl-ferro-paper));
  --fxl-ferro-rule: color-mix(in oklch, var(--fxl-ferro-ink) 13%, transparent);
  --fxl-ferro-chip: color-mix(in oklch, var(--fxl-ferro-paper) 76%, white);
  --fxl-ferro-out: cubic-bezier(.2, .9, .2, 1);
  --fxl-ferro-spring: linear(0, 0.1 5%, 0.45 14%, 0.88 25%, 1.06 33%, 1.08 39%, 1.04 47%, 0.99 62%, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 5 / 4.4;
  min-block-size: 230px;
  max-block-size: 400px;
  display: grid;
  grid-template-areas: "head coil" ". ." "read read";
  grid-template-columns: 1fr auto;
  grid-template-rows: auto 1fr auto;
  padding: clamp(12px, 4.2cqi, 18px);
  border-radius: 18px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxl-ferro-ink);
  background:
    radial-gradient(90% 70% at 50% 18%, color-mix(in oklch, white 70%, var(--fxl-ferro-paper)), transparent 70%),
    linear-gradient(var(--fxl-ferro-paper), color-mix(in oklch, var(--fxl-ferro-ink) 9%, var(--fxl-ferro-paper)));
  box-shadow: inset 0 0 0 1px var(--fxl-ferro-rule);
  font: 400 12px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3, dl, dd) { margin: 0; }
}
.fxl-ferro .fxl-ferro-cv,
.fxl-ferro .fxl-ferro-bench { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
.fxl-ferro .fxl-ferro-cv { display: block; }
.fxl-ferro .fxl-ferro-probe { position: absolute; inline-size: 0; block-size: 0; overflow: hidden; }
.fxl-ferro .fxl-ferro-bench {
  z-index: 1;
  outline: none;
  cursor: none;
  touch-action: pan-y;
  border-radius: inherit;
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--fxl-ferro-copper), inset 0 0 0 6px color-mix(in oklch, var(--fxl-ferro-copper) 18%, transparent); }
}
.fxl-ferro .fxl-ferro-head,
.fxl-ferro .fxl-ferro-read { position: relative; z-index: 2; pointer-events: none; }
.fxl-ferro .fxl-ferro-head { grid-area: head; display: grid; gap: 3px; align-self: start; }
.fxl-ferro .fxl-ferro-eyebrow {
  font: 600 9.5px/1.2 ui-monospace, Menlo, monospace;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--fxl-ferro-muted);
}
.fxl-ferro .fxl-ferro-title {
  font-size: clamp(14px, 5cqi, 18px);
  font-weight: 700;
  letter-spacing: -.02em;
  text-wrap: balance;
}
.fxl-ferro .fxl-ferro-coil {
  grid-area: coil;
  position: relative;
  z-index: 2;
  align-self: start;
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  block-size: 32px;
  padding: 0 12px 0 9px;
  border: 1px solid var(--fxl-ferro-rule);
  border-radius: 999px;
  background: var(--fxl-ferro-chip);
  color: var(--fxl-ferro-ink);
  font: 650 11.5px/1 system-ui, sans-serif;
  cursor: pointer;
  transition: background .25s, color .25s, border-color .25s, scale .45s var(--fxl-ferro-spring);
  & svg { inline-size: 16px; block-size: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  &[aria-pressed="true"] {
    background: var(--fxl-ferro-copper);
    border-color: color-mix(in oklch, var(--fxl-ferro-copper) 70%, black);
    color: color-mix(in oklch, var(--fxl-ferro-copper) 12%, white);
    box-shadow: 0 0 0 3px color-mix(in oklch, var(--fxl-ferro-copper) 22%, transparent);
  }
  &:active { scale: .94; }
  &:focus-visible { outline: 2px solid var(--fxl-ferro-ink); outline-offset: 2px; }
}
.fxl-ferro .fxl-ferro-read {
  grid-area: read;
  display: flex;
  align-items: flex-end;
  gap: clamp(10px, 4.5cqi, 20px);
  font-variant-numeric: tabular-nums;
  & > div { display: grid; gap: 2px; }
  & dt {
    font: 600 8.5px/1.2 ui-monospace, Menlo, monospace;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: var(--fxl-ferro-muted);
    white-space: nowrap;
  }
  & dd { display: flex; align-items: baseline; gap: 2px; }
  & b { font-size: 15px; font-weight: 700; letter-spacing: -.02em; }
  & span { font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--fxl-ferro-muted); }
  & .fxl-ferro-big { margin-inline-end: auto; }
  & .fxl-ferro-big b { font-size: clamp(22px, 8.4cqi, 30px); font-weight: 300; letter-spacing: -.05em; line-height: .95; min-inline-size: 3ch; }
}
@container (max-width: 290px) {
  .fxl-ferro .fxl-ferro-state { display: none; }
  .fxl-ferro .fxl-ferro-coil { padding: 0 8px; }
}

@media (prefers-reduced-motion: reduce) {
  .fxl-ferro .fxl-ferro-coil { transition: background .25s, color .25s, border-color .25s; }
  .fxl-ferro .fxl-ferro-coil:active { scale: 1; }
}

