const cv = root.querySelector('.fxl-ferro-cv');
const bench = root.querySelector('.fxl-ferro-bench');
const probe = root.querySelector('.fxl-ferro-probe');
const coilBtn = root.querySelector('.fxl-ferro-coil');
const stateEl = root.querySelector('.fxl-ferro-state');
const bEl = root.querySelector('.fxl-ferro-b');
const gapEl = root.querySelector('.fxl-ferro-gap');
const nEl = root.querySelector('.fxl-ferro-n');
const ctx = cv.getContext('2d');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* The Rosensweig instability, side on. The coil's on-axis field falls off like a short
   solenoid, B = B0 / (1 + (z/z0)^2)^1.5, and spreads sideways with the same law. Where
   the field beats the critical value the flat surface gives way to a lattice of cones
   at the capillary spacing; every cone has its own damped spring, so they rise late,
   overshoot and settle, and collapse with a wobble when the coil is cut. */
const B0 = 480, Z0 = 9, BC = 22, DISH_MM = 60;
let W = 0, H = 0, dpr = 1, x0 = 0, x1 = 0, floorY = 0, base = 0, lam = 12, mmpx = 1, amax = 30;
let mx = 0, my = 0, tmx = 0, tmy = 0, on = true, lastInput = -1e9, raf = 0, last = 0, visible = true, uiAt = 0;
const K = 9;                                   /* cones each side of the axis, per row */
const amp = new Float32Array(4 * K + 2), vel = new Float32Array(4 * K + 2);
let bulge = 0, bulgeV = 0, col = null;

function colours() {
  const get = (n, fb) => { probe.style.color = 'var(' + n + ')'; return getComputedStyle(probe).color || fb; };
  col = { fluid: get('--fxl-ferro-fluid', '#15171d'), copper: get('--fxl-ferro-copper', '#c0723a'), ink: get('--fxl-ferro-ink', '#2a2d35'), paper: get('--fxl-ferro-paper', '#efede8') };
}
function layout() {
  W = cv.clientWidth; H = cv.clientHeight;
  if (!W || !H) return;
  dpr = Math.min(2, devicePixelRatio || 1);
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  x0 = W * 0.09; x1 = W * 0.91; floorY = H - Math.max(74, H * 0.24); base = floorY - 15;
  mmpx = DISH_MM / (x1 - x0); lam = (x1 - x0) / 16; amax = Math.min(H * 0.17, lam * 2.2);
  if (!mx) { mx = tmx = W * 0.5; my = tmy = base - H * 0.2; }
  colours();
}
const gapMm = () => Math.max(0.5, (base - (my + 15)) * mmpx);
const fieldAt = (dxpx) => {
  if (!on) return 0;
  const z = gapMm(), r = dxpx * mmpx;
  return B0 / Math.pow(1 + (z * z + r * r * 0.6) / (Z0 * Z0), 1.5);
};
function targetFor(B) {
  if (B <= BC) return 0;
  return amax * Math.pow(Math.min(1, (B - BC) / 260), 0.55);
}

function sim(dt) {
  const calm = reduce.matches;
  const kS = calm ? 120 : 170, cS = calm ? 24 : 9;
  for (let r = 0; r < 2; r++) {
    for (let k = -K; k <= K; k++) {
      const idx = r * (2 * K + 1) + k + K;
      const xk = mx + (k + (r ? 0.5 : 0)) * lam;
      let t = (xk < x0 + lam * 0.6 || xk > x1 - lam * 0.6) ? 0 : targetFor(fieldAt(xk - mx)) * (r ? 0.72 : 1);
      const reach = base - (my + 17), off = Math.abs(xk - mx);
      if (off < 22) t = Math.min(t, reach * (0.86 + off * 0.004));   /* nothing grows through the pole */
      if (r === 0 && k === 0 && on && reach < amax * 1.15) t = Math.max(t, reach);  /* the centre cone leaps the gap */
      vel[idx] += ((t - amp[idx]) * kS - vel[idx] * cS) * dt;
      amp[idx] += vel[idx] * dt;
      if (amp[idx] < 0) { amp[idx] = 0; vel[idx] *= -0.3; }
    }
  }
  const bt = on ? Math.min(10, fieldAt(0) / 26) : 0;
  bulgeV += ((bt - bulge) * 60 - bulgeV * 10) * dt; bulge += bulgeV * dt;
}

function surfaceY(x) {
  const d = (x - mx) / (lam * 3.2);
  return base - bulge * Math.exp(-d * d);
}
function cone(xk, a, lean, w) {
  const by = surfaceY(xk), tx = xk + lean, ty = by - a;
  ctx.moveTo(xk - w, surfaceY(xk - w) + 0.5);
  ctx.quadraticCurveTo(xk - w * 0.22, by - a * 0.1, tx, ty);
  ctx.quadraticCurveTo(xk + w * 0.22, by - a * 0.1, xk + w, surfaceY(xk + w) + 0.5);
  ctx.closePath();
}

function draw() {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  const ink = col.ink;
  /* dish: a heavy glass petri dish seen almost edge on, with its shadow on the bench */
  const sh = ctx.createLinearGradient(0, floorY + 6, 0, floorY + 30);
  sh.addColorStop(0, 'rgba(20,24,32,0.2)'); sh.addColorStop(1, 'rgba(20,24,32,0)');
  ctx.fillStyle = sh; ctx.fillRect(x0 - 12, floorY + 6, x1 - x0 + 24, 24);
  ctx.fillStyle = 'rgba(255,255,255,0.4)';
  ctx.beginPath(); ctx.roundRect(x0 - 6, floorY - 22, x1 - x0 + 12, 30, [3, 3, 9, 9]); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.55)';
  ctx.beginPath(); ctx.ellipse((x0 + x1) / 2, floorY - 21, (x1 - x0) / 2 + 5, 3, 0, 0, 6.2832); ctx.fill();

  /* field lines when powered: faint arcs from the pole face into the fluid */
  if (on) {
    const gs = Math.min(1, fieldAt(0) / 120);
    ctx.strokeStyle = 'rgba(40,50,70,' + (0.05 + gs * 0.1) + ')'; ctx.lineWidth = 1; ctx.setLineDash([2, 4]);
    for (let s = -3; s <= 3; s++) {
      if (!s) continue;
      ctx.beginPath(); ctx.moveTo(mx + s * 3, my + 17);
      ctx.bezierCurveTo(mx + s * 16, my + 30, mx + s * lam * 1.6, base - 20, mx + s * lam * 1.8, base);
      ctx.stroke();
    }
    ctx.setLineDash([]);
  }

  /* back row first, a shade lifted by the sheen of the room */
  for (let r = 1; r >= 0; r--) {
    ctx.fillStyle = col.fluid;
    ctx.beginPath();
    for (let k = -K; k <= K; k++) {
      const idx = r * (2 * K + 1) + k + K, a = amp[idx];
      if (a < 0.6) continue;
      const xk = mx + (k + (r ? 0.5 : 0)) * lam;
      const lean = (mx - xk) * Math.min(0.18, a / (amax * 4));
      cone(xk, a, lean, lam * (r ? 0.5 : 0.58));
    }
    ctx.fill();
    if (r) { ctx.fillStyle = 'rgba(200,210,235,0.13)'; ctx.fill(); }
    if (r === 1) {
      /* the puddle itself */
      ctx.fillStyle = col.fluid;
      ctx.beginPath();
      ctx.moveTo(x0 + 6, floorY);
      ctx.quadraticCurveTo(x0, base, x0 + 10, base);
      for (let x = x0 + 10; x <= x1 - 10; x += 3) ctx.lineTo(x, surfaceY(x));
      ctx.lineTo(x1 - 10, surfaceY(x1 - 10));
      ctx.quadraticCurveTo(x1, base, x1 - 6, floorY);
      ctx.closePath(); ctx.fill();
    }
  }
  /* glints: the softbox above-left catches the left flank and the tip of every cone */
  ctx.lineCap = 'round';
  for (let k = -K; k <= K; k++) {
    const a = amp[k + K];
    if (a < 3) continue;
    const xk = mx + k * lam, by = surfaceY(xk), lean = (mx - xk) * Math.min(0.18, a / (amax * 4));
    const tx = xk + lean, ty = by - a, w = lam * 0.58;
    const g = ctx.createLinearGradient(xk - w, by, tx, ty);
    g.addColorStop(0, 'rgba(255,255,255,0)'); g.addColorStop(0.7, 'rgba(225,232,250,0.32)'); g.addColorStop(1, 'rgba(255,255,255,0.75)');
    ctx.strokeStyle = g; ctx.lineWidth = 0.9;
    ctx.beginPath(); ctx.moveTo(xk - w * 0.5, by - a * 0.1);
    ctx.quadraticCurveTo(xk - w * 0.14, by - a * 0.3, tx - 0.6, ty + 1.6);
    ctx.stroke();
  }
  /* long reflection on the puddle surface */
  const rg = ctx.createLinearGradient(x0, 0, x1, 0);
  rg.addColorStop(0, 'rgba(255,255,255,0)'); rg.addColorStop(0.3, 'rgba(255,255,255,0.32)'); rg.addColorStop(0.7, 'rgba(255,255,255,0.08)'); rg.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.strokeStyle = rg; ctx.lineWidth = 1.2;
  ctx.beginPath();
  for (let x = x0 + 14; x <= x1 - 14; x += 3) { const y = surfaceY(x) + 1.6; x === x0 + 14 ? ctx.moveTo(x, y) : ctx.lineTo(x, y); }
  ctx.stroke();
  /* the front wall of the dish, over the fluid: a faint pane, a lit rim, a thick foot */
  ctx.fillStyle = 'rgba(255,255,255,0.1)';
  ctx.beginPath(); ctx.roundRect(x0 - 6, floorY - 22, x1 - x0 + 12, 30, [3, 3, 9, 9]); ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.9)'; ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(x0 - 6, floorY - 22); ctx.lineTo(x0 - 6, floorY - 1); ctx.quadraticCurveTo(x0 - 6, floorY + 8, x0 + 4, floorY + 8);
  ctx.lineTo(x1 - 4, floorY + 8); ctx.quadraticCurveTo(x1 + 6, floorY + 8, x1 + 6, floorY - 1); ctx.lineTo(x1 + 6, floorY - 22); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.7)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0 + 8, floorY + 4.5); ctx.lineTo(x1 - 8, floorY + 4.5); ctx.stroke();
  ctx.strokeStyle = 'rgba(30,40,60,0.2)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x0, floorY + 9.5); ctx.lineTo(x1, floorY + 9.5); ctx.stroke();

  /* the electromagnet on its rod */
  ctx.fillStyle = 'rgba(40,46,58,0.5)'; ctx.fillRect(mx - 1.5, -2, 3, my - 14);
  const cw = 26, chh = 30, cx = mx - cw / 2, cy = my - 15;
  const body = ctx.createLinearGradient(cx, 0, cx + cw, 0);
  body.addColorStop(0, '#7b5136'); body.addColorStop(0.35, col.copper); body.addColorStop(0.55, '#f2c9a0'); body.addColorStop(1, '#6a4128');
  ctx.fillStyle = body;
  ctx.beginPath(); ctx.roundRect(cx, cy, cw, chh - 6, 3); ctx.fill();
  ctx.strokeStyle = 'rgba(60,30,15,0.35)'; ctx.lineWidth = 0.7;
  for (let y = cy + 3; y < cy + chh - 7; y += 2.4) { ctx.beginPath(); ctx.moveTo(cx + 1, y); ctx.lineTo(cx + cw - 1, y + 0.8); ctx.stroke(); }
  const pole = ctx.createLinearGradient(cx, 0, cx + cw, 0);
  pole.addColorStop(0, '#6c717c'); pole.addColorStop(0.5, '#e7eaf0'); pole.addColorStop(1, '#5b606a');
  ctx.fillStyle = pole;
  ctx.beginPath(); ctx.roundRect(cx - 2, cy + chh - 7, cw + 4, 6, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(cx - 2, cy - 4, cw + 4, 5, 2); ctx.fill();
  if (on) {
    ctx.fillStyle = 'rgba(255,170,90,0.9)';
    ctx.beginPath(); ctx.arc(cx + cw - 5, cy + 4, 1.6, 0, 6.2832); ctx.fill();
  }
  /* a bead of fluid clings to the pole once the centre cone has reached it */
  const reach = base - (my + 17);
  if (on && amp[K] >= reach - 1.5 && reach < amax * 1.15) {
    ctx.fillStyle = col.fluid;
    ctx.beginPath(); ctx.ellipse(mx, my + 16, 9, 3.5, 0, 0, 6.2832); ctx.fill();
  }
}

function readout(now) {
  if (now - uiAt < 90) return;
  uiAt = now;
  bEl.textContent = Math.round(fieldAt(0));
  gapEl.textContent = gapMm().toFixed(1);
  let n = 0;
  for (let i = 0; i < 2 * K + 1; i++) if (amp[i] > 3) n++;
  nEl.textContent = n;
}

function step(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible || !W) return;
  const dt = Math.min(0.033, (now - last) / 1000 || 0.016); last = now;
  const calm = reduce.matches;
  if (!calm && now - lastInput > 3200) {
    const t = now / 1000;
    tmx = W * (0.5 + 0.22 * Math.sin(t * 0.42)); tmy = base - H * (0.19 + 0.07 * Math.sin(t * 0.67 + 1.2));
  }
  const f = 1 - Math.pow(calm ? 0.0001 : 0.002, dt);
  mx += (tmx - mx) * f; my += (tmy - my) * f;
  for (let s = 0; s < 2; s++) sim(dt / 2);
  draw();
  readout(now);
  let moving = Math.abs(tmx - mx) + Math.abs(tmy - my) > 0.1;
  for (let i = 0; i < vel.length && !moving; i++) if (Math.abs(vel[i]) > 0.05) moving = true;
  if (moving || !calm) raf = requestAnimationFrame(step);
}
function kick() { if (!raf && visible && root.isConnected && W) { last = performance.now(); raf = requestAnimationFrame(step); } }

function aim(e) {
  const r = cv.getBoundingClientRect();
  tmx = Math.max(x0, Math.min(x1, e.clientX - r.left));
  tmy = Math.max(H * 0.2, Math.min(base - 18, e.clientY - r.top));
  lastInput = performance.now(); kick();
}
bench.addEventListener('pointermove', (e) => { if (e.pointerType === 'mouse' || e.buttons) aim(e); });
bench.addEventListener('pointerdown', (e) => { aim(e); try { bench.setPointerCapture(e.pointerId); } catch (err) {} });
function setCoil(v) {
  on = v;
  coilBtn.setAttribute('aria-pressed', v ? 'true' : 'false');
  stateEl.textContent = v ? 'Coil on' : 'Coil off';
  if (!v) for (let i = 0; i < vel.length; i++) vel[i] -= amp[i] * 2;   /* a sharp collapse, then the wobble */
  lastInput = performance.now(); kick();
}
coilBtn.addEventListener('click', () => setCoil(!on));
bench.addEventListener('keydown', (e) => {
  const sx = Math.max(8, W * 0.04), sy = Math.max(6, H * 0.035);
  const mv = { ArrowLeft: [-sx, 0], ArrowRight: [sx, 0], ArrowUp: [0, -sy], ArrowDown: [0, sy] }[e.key];
  if (mv) {
    e.preventDefault();
    tmx = Math.max(x0, Math.min(x1, tmx + mv[0])); tmy = Math.max(H * 0.2, Math.min(base - 18, tmy + mv[1]));
    lastInput = performance.now() + 4000; kick();
  } else if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); setCoil(!on); }
});

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } layout(); if (W) draw(); kick(); });
ro.observe(cv);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
const onVis = () => {
  if (!root.isConnected) { document.removeEventListener('visibilitychange', onVis); return; }
  if (!document.hidden) kick();
};
document.addEventListener('visibilitychange', onVis);
reduce.addEventListener('change', kick);
layout();
/* settle the cones under the starting magnet so the first frame already stands */
for (let n = 0; n < 120; n++) sim(1 / 120);
kick();

