.fxl-swipe {
  /* Re-theme per slide with --bg and --ink on each article; these set the chrome. */
  --fxl-swipe-ink: oklch(0.97 0.025 75);
  --fxl-swipe-font: system-ui, -apple-system, "Segoe UI", sans-serif;
  --fxl-swipe-out: cubic-bezier(.16, 1, .3, 1);
  --fxl-swipe-spring: linear(0, 0.1 5%, 0.45 14%, 0.88 25%, 1.06 33%, 1.08 39%, 1.04 47%, 0.99 62%, 1);

  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  inline-size: 100%;
  aspect-ratio: 1 / 1.12;
  min-block-size: 300px;
  max-block-size: 430px;
  border-radius: 22px;
  overflow: hidden;
  isolation: isolate;
  color: var(--fxl-swipe-ink);
  background: oklch(0.6 0.135 40);
  font: 400 12px/1.4 var(--fxl-swipe-font);
  -webkit-font-smoothing: antialiased;
  touch-action: pan-y;
  user-select: none;
  transition: color .5s var(--fxl-swipe-out);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3) { margin: 0; }
  &[data-slide="1"] { --fxl-swipe-ink: oklch(0.28 0.06 175); }
  &[data-slide="2"] { --fxl-swipe-ink: oklch(0.93 0.04 75); }
}
.fxl-swipe .fxl-swipe-track { position: absolute; inset: 0; }
.fxl-swipe .fxl-swipe-slide {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-areas: "top" "pic" "title" "body" "cta";
  grid-template-rows: auto minmax(0, 1fr) auto auto auto;
  align-content: end;
  padding: clamp(16px, 6cqi, 26px) clamp(18px, 7cqi, 30px) clamp(52px, 15cqi, 62px);
  background:
    radial-gradient(80% 50% at 50% 34%, color-mix(in oklch, var(--ink) 9%, transparent), transparent 70%),
    var(--bg);
  color: var(--ink);
  visibility: hidden;
  &[data-state="cur"], &[data-state="in"] { visibility: visible; }
  &[data-state="cur"] { z-index: 1; }
  &[data-state="in"] { z-index: 2; }
}
.fxl-swipe .fxl-swipe-top {
  grid-area: top;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-inline-end: 8px;
  font: 600 10px/1 ui-monospace, Menlo, monospace;
  letter-spacing: .12em;
  text-transform: uppercase;
}
.fxl-swipe .fxl-swipe-step { font-variant-numeric: tabular-nums; opacity: .72; }
.fxl-swipe .fxl-swipe-kicker {
  padding: 5px 9px;
  border-radius: 999px;
  border: 1px solid color-mix(in oklch, var(--ink) 30%, transparent);
}
.fxl-swipe .fxl-swipe-pic {
  grid-area: pic;
  position: relative;
  min-block-size: 0;
}
.fxl-swipe .fxl-swipe-art {
  position: absolute;
  inset: 0;
  margin: auto;
  inline-size: min(64cqi, 100%);
  block-size: 100%;
  max-block-size: 150px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  overflow: visible;
  & .fxl-swipe-fill { fill: color-mix(in oklch, var(--ink) 14%, transparent); stroke: none; }
  & .fxl-swipe-fill2 { fill: color-mix(in oklch, var(--ink) 28%, transparent); stroke: none; }
}
.fxl-swipe .fxl-swipe-title {
  grid-area: title;
  margin-block-start: 6px;
  font-size: clamp(22px, 9cqi, 32px);
  font-weight: 760;
  letter-spacing: -.035em;
  line-height: 1.02;
  text-wrap: balance;
}
.fxl-swipe .fxl-swipe-body {
  grid-area: body;
  margin-block-start: 8px;
  max-inline-size: 34ch;
  font-size: clamp(12px, 3.9cqi, 14px);
  line-height: 1.45;
  opacity: .86;
  text-wrap: pretty;
}
.fxl-swipe .fxl-swipe-cta {
  grid-area: cta;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  margin-block-start: 14px;
}
.fxl-swipe .fxl-swipe-book {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  block-size: 38px;
  padding: 0 16px 0 12px;
  border: 0;
  border-radius: 999px;
  background: var(--ink);
  color: var(--bg);
  font: 700 13px/1 var(--fxl-swipe-font);
  cursor: pointer;
  transition: scale .45s var(--fxl-swipe-spring), background .3s;
  & svg { inline-size: 18px; block-size: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & .fxl-swipe-ico-ok { display: none; }
  &[aria-pressed="true"] { background: oklch(0.72 0.17 50); color: oklch(0.2 0.03 45); }
  &[aria-pressed="true"] .fxl-swipe-ico-ok { display: block; }
  &[aria-pressed="true"] .fxl-swipe-ico-cal { display: none; }
  &:active { scale: .95; }
  &:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
}
.fxl-swipe .fxl-swipe-note {
  font: 500 10.5px/1.2 ui-monospace, Menlo, monospace;
  opacity: .78;
  font-variant-numeric: tabular-nums;
}

/* the current slide's content rises in, staggered, once the liquid has settled */
.fxl-swipe .fxl-swipe-slide[data-enter] :is(.fxl-swipe-top, .fxl-swipe-pic, .fxl-swipe-title, .fxl-swipe-body, .fxl-swipe-cta) {
  animation: fxl-swipe-rise .7s var(--fxl-swipe-out) both;
  animation-delay: calc(var(--i) * 55ms);
}
@keyframes fxl-swipe-rise {
  from { opacity: 0; translate: 0 14px; filter: blur(3px); }
  to { opacity: 1; translate: 0 0; filter: blur(0); }
}
.fxl-swipe .fxl-swipe-slide[data-enter] .fxl-swipe-spin { animation: fxl-swipe-spin 1.4s var(--fxl-swipe-out) both; }
@keyframes fxl-swipe-spin { from { stroke-dasharray: 0 60; } to { stroke-dasharray: 60 0; } }
.fxl-swipe .fxl-swipe-drip { animation: fxl-swipe-drip 2.6s cubic-bezier(.5, 0, .75, 0) infinite; }
@keyframes fxl-swipe-drip {
  0%, 30% { stroke-dasharray: 0 30; }
  70%, 100% { stroke-dasharray: 16 30; }
}
.fxl-swipe .fxl-swipe-flame { fill: oklch(0.72 0.17 50); stroke: none; transform-origin: 80px 74px; animation: fxl-swipe-flicker 1.8s ease-in-out infinite alternate; }
@keyframes fxl-swipe-flicker {
  0% { scale: 1 1; }
  50% { scale: .94 1.07; }
  100% { scale: 1.04 .96; }
}

/* chrome above the slides */
.fxl-swipe .fxl-swipe-next {
  position: absolute;
  z-index: 4;
  left: 0;
  top: 0;
  inline-size: 40px;
  block-size: 40px;
  translate: calc(var(--fxl-swipe-nx, 0) * 1px - 50%) calc(var(--fxl-swipe-ny, 0) * 1px - 50%);
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--fxl-swipe-next-ink, currentColor);
  cursor: pointer;
  opacity: var(--fxl-swipe-na, 1);
  & svg { inline-size: 20px; block-size: 20px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  &:focus-visible { outline: 2px solid currentColor; outline-offset: -4px; }
  &[hidden] { display: none; }
}
.fxl-swipe .fxl-swipe-prev {
  position: absolute;
  z-index: 4;
  left: clamp(8px, 3cqi, 14px);
  bottom: clamp(12px, 4cqi, 18px);
  inline-size: 34px;
  block-size: 34px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid color-mix(in oklch, var(--fxl-swipe-ink) 30%, transparent);
  border-radius: 50%;
  background: transparent;
  color: var(--fxl-swipe-ink);
  cursor: pointer;
  transition: opacity .3s, scale .45s var(--fxl-swipe-spring), color .5s;
  & svg { inline-size: 18px; block-size: 18px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  &:disabled { opacity: 0; scale: .7; pointer-events: none; }
  &:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
}
.fxl-swipe .fxl-swipe-dots {
  position: absolute;
  z-index: 4;
  left: 50%;
  bottom: clamp(22px, 6.5cqi, 28px);
  translate: -50% 0;
  display: flex;
  gap: 2px;
}
.fxl-swipe .fxl-swipe-dot {
  inline-size: 22px;
  block-size: 22px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
  display: grid;
  place-items: center;
  &::before {
    content: "";
    inline-size: 7px;
    block-size: 7px;
    border-radius: 999px;
    background: var(--fxl-swipe-ink);
    opacity: .35;
    transition: inline-size .5s var(--fxl-swipe-spring), opacity .3s, background .5s;
  }
  &[aria-current="step"]::before { inline-size: 20px; opacity: 1; }
  &:hover::before { opacity: .7; }
  &:focus-visible { outline: 2px solid var(--fxl-swipe-ink); outline-offset: -2px; border-radius: 6px; }
}
.fxl-swipe .fxl-swipe-brand {
  position: absolute;
  z-index: 4;
  right: clamp(14px, 5cqi, 22px);
  bottom: clamp(24px, 7cqi, 30px);
  font: 800 11px/1 var(--fxl-swipe-font);
  letter-spacing: .02em;
  color: var(--fxl-swipe-ink);
  opacity: .8;
  pointer-events: none;
  transition: color .5s;
}
@container (max-width: 300px) {
  .fxl-swipe .fxl-swipe-brand { display: none; }
  .fxl-swipe .fxl-swipe-note { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .fxl-swipe .fxl-swipe-slide[data-enter] :is(.fxl-swipe-top, .fxl-swipe-pic, .fxl-swipe-title, .fxl-swipe-body, .fxl-swipe-cta) { animation: fxl-swipe-fade .3s linear both; animation-delay: 0s; }
  .fxl-swipe .fxl-swipe-slide[data-enter] .fxl-swipe-spin,
  .fxl-swipe .fxl-swipe-drip,
  .fxl-swipe .fxl-swipe-flame { animation: none; }
  .fxl-swipe .fxl-swipe-book, .fxl-swipe .fxl-swipe-prev { transition: opacity .3s; }
  .fxl-swipe .fxl-swipe-dot::before { transition: opacity .3s; }
}
@keyframes fxl-swipe-fade { from { opacity: 0; } to { opacity: 1; } }

