const slides = [...root.querySelectorAll('.fxl-swipe-slide')];
const nextBtn = root.querySelector('.fxl-swipe-next');
const prevBtn = root.querySelector('.fxl-swipe-prev');
const dots = [...root.querySelectorAll('.fxl-swipe-dot')];
const book = root.querySelector('.fxl-swipe-book');
const bookLabel = root.querySelector('.fxl-swipe-booklabel');
const note = root.querySelector('.fxl-swipe-note');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const titles = slides.map((s) => s.querySelector('.fxl-swipe-title').textContent);

/* Liquid swipe: the incoming slide sits on top, clipped by a path() whose edge is a
   cosine bell. Four sprung numbers drive it: the bell's centre and its horizontal and
   vertical radii, plus a solid band that grows from the edge. Commit and the band
   floods the card; let go early and the bell springs home with an overshoot. */
let W = 0, H = 0, cur = 0, inc = 1, dir = 1, busy = false;
const P = { cy: 0, hr: 0, vr: 0, side: 0 }, V = { cy: 0, hr: 0, vr: 0, side: 0 }, T = { cy: 0, hr: 0, vr: 0, side: 0 };
let drag = null, raf = 0, last = 0, visible = true, lastInput = -1e9, onDone = null;

function rest() {
  T.cy = H * 0.6; T.hr = Math.min(30, W * 0.085); T.vr = Math.min(86, H * 0.2); T.side = 0;
}
function measure() {
  W = root.clientWidth; H = root.clientHeight;
  if (!W) return;
